insert into public.guia_animais (slug, nome, sinonimos, especie, subgrupo, tipo, classificacao, finalidade, resumo, sistemas, fases, fase_estudo, peso_min_kg, peso_max_kg, peso_nota, consumo_ref, consumo_unidade, consumo_fatores, tipos_alimentacao, forma_fisica, materias_comuns, restricoes, perguntas, sinais_falta_info, processo, equipamentos, argumento, promessas_proibidas, branorte, explicar_cliente, resumo_30s, regiao, imagem_slug, emoji, status, pendente_validacao, pendencias, fontes, autor, revisor_tecnico, revisado_em, proxima_revisao, ordem) values
  ('nelore', 'Nelore', '{"Nelore Padrão","Nelore Mocho","Nelore PO"}'::text[], 'bovinos', 'corte', 'raca', 'Zebuíno (Bos indicus)', 'Corte — cria, recria e engorda, majoritariamente a pasto.', 'Zebuíno predominante no rebanho de corte brasileiro. Rústico, tolera calor, umidade e carga de ectoparasitas, com boa fertilidade a pasto. Menos precoce e com menor deposição de marmoreio que os taurinos.', '{"pasto","semiconfinamento","confinamento"}'::text[], '{"gado_corte","cria","recria","engorda","manutencao","proteica","semi_confinamento","confinamento"}'::text[], 'manutencao', null, null, 'Faixa de referencia de campo, nao indice garantido: vaca adulta em torno de 450-500 kg e touro acima de 800 kg. O numero nao vem de tabela oficial - peso real depende de idade, condicao corporal, linha genetica e manejo. Confirme com o cliente ou com o tecnico dele antes de usar em proposta.', 'O consumo-alvo de suplemento a pasto é definido na formulação e no rótulo do produto, e varia com categoria animal, época do ano (seca/águas), qualidade do pasto e tipo de produto (mineral puro, proteinado, proteico-energético). Trate qualquer faixa como referência; o número oficial é o do programa nutricional da fazenda.', null, '{}'::text[], '{"sal mineral","mineral proteico (proteinado)","proteico-energético de seca","ração de terminação em confinamento"}'::text[], '{"farelada"}'::text[], '{"sal-comum","sal-mineral","calcario-calcitico","fosfato-bicalcico","nucleo-premix","ureia","farelo-soja","milho","caroco-algodao","farelo-algodao","concentrado-proteico","adsorvente-micotoxinas"}'::text[], '{"A Branorte fornece equipamento para ração FARELADA e mistura mineral. Não fornece peletizadora nem extrusora.","Formulação nutricional é responsabilidade do técnico do cliente; a Branorte não formula dieta."}'::text[], '{"Quantas cabeças, e como se divide entre cria, recria e engorda?","O senhor compra mineral e proteinado prontos ensacados, ou já mistura alguma coisa na fazenda?","Na seca o senhor passa proteinado, semiconfina ou só segura no pasto?","Tem confinamento ou terminação intensiva de alguma parte do rebanho?","Quem faz a formulação do suplemento: técnico próprio, revenda ou o fornecedor do núcleo?"}'::text[], '{}'::text[], 'Dois produtos diferentes, duas linhas de equipamento. Mineral e proteinado: pesagem (balança/caçamba de pesagem) + misturador horizontal + ensacadeira. Ração de semiconfinamento ou confinamento: moinho de martelo para o grão + misturador + transporte até o cocho. Não confunda os dois na hora de dimensionar.', '{"MISTURADOR","BALANCA","CACAMBA_PESAGEM","ENSACADEIRA","TRANSPORTADOR","MOEGA","SUPORTE_BAG","MOINHO"}'::text[], 'Rebanho de Nelore a pasto consome suplemento o ano inteiro — mineral nas águas, proteinado na seca. Quem tem escala compra volume todo mês, com frete e margem do intermediário embutidos no saco. Produzir a mistura na fazenda tira essas duas camadas do custo e dá controle sobre a homogeneidade do lote.', '{"Não prometer ganho de peso, conversão alimentar ou peso à desmama como resultado do equipamento.","Não afirmar percentual de participação do Nelore no rebanho nacional (usar ''predominante'', sem número).","Não citar economia em R$/cabeça sem ter na mão os preços de ingrediente e de suplemento pronto do próprio cliente.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'Hoje o senhor compra mineral e proteinado prontos, ensacados, com frete embutido. Com misturador e balanca na fazenda o senhor compra os ingredientes e faz a mistura aqui. A formula continua sendo a do seu tecnico - o equipamento repete a mesma mistura todo dia, desde que a sequencia de carga e o tempo de mistura sejam respeitados.', 'Nelore é gado de pasto: come mineral e proteinado, não ração completa. O equipamento que interessa aqui é misturador horizontal com pesagem, para fazer a mistura mineral na fazenda. Moinho só entra se ele moer grão para semiconfinamento ou confinamento. Pergunte primeiro qual produto ele faz — mineral ou ração — porque a máquina muda.', 'Todo o Brasil, com maior concentração no Centro-Oeste, Norte, Sudeste e MATOPIBA.', 'nelore', '🐂', 'aprovado', true, '{"Confirmar com o técnico as faixas de consumo por categoria antes de usar em proposta.","Validar dimensionamento de misturador por lote de mistura mineral com a engenharia."}'::text[], '{"embrapa-gado-corte","abcz","mapa-alimentacao-animal","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1010),
  ('angus', 'Angus (Aberdeen Angus)', '{"Aberdeen Angus","Black Angus","Red Angus"}'::text[], 'bovinos', 'corte', 'raca', 'Taurino (Bos taurus) britânico', 'Corte de acabamento — terminação em confinamento e uso como raça paterna em cruzamento industrial.', 'Taurino britânico de maturidade precoce, bom acabamento de gordura e deposição de marmoreio. Pouco adaptado ao calor e à carga de parasitas do trópico, razão pela qual no Brasil aparece muito como touro ou sêmen sobre matriz zebuína.', '{"confinamento","semiconfinamento","pasto"}'::text[], '{"gado_corte","recria","engorda","confinamento","semi_confinamento"}'::text[], 'confinamento', null, null, 'Animal de abate jovem, com acabamento antes dos taurinos tardios. Peso de abate depende do programa de bonificação e do frigorífico que compra.', 'Consumo de matéria seca e proporção concentrado/volumoso na terminação são definidos pelo nutricionista conforme peso de entrada, dias de cocho e meta de acabamento. Não trabalhe com percentual fechado de dieta em proposta.', null, '{}'::text[], '{"ração de terminação de alto concentrado","suplemento de recria","sal mineral"}'::text[], '{"farelada"}'::text[], '{"milho","sorgo","farelo-soja","caroco-algodao","casquinha-soja","silagem-volumoso","ddg-ddgs","calcario-calcitico","sal-mineral","nucleo-premix","ureia","bicarbonato-sodio","oleo-gordura","adsorvente-micotoxinas"}'::text[], '{"Equipamento Branorte produz racao FARELADA; peletizacao exige processo adicional nao incluido.","A linha processa ingrediente seco. Volumoso (silagem, feno) nao passa por moinho nem por misturador - dimensionar somente o concentrado.","Oleo e gordura sao ingredientes liquidos: so entram na mistura com sistema de dosagem especifico. Confirmar com a engenharia antes de incluir na proposta.","Dieta de alto concentrado exige acompanhamento de nutricionista - a Branorte nao formula."}'::text[], '{"Quantas cabeças o senhor confina por ciclo e quantos ciclos por ano?","Quantos dias de cocho no programa que o senhor segue?","O grão é da própria fazenda ou comprado? Chega em que umidade?","O senhor está em algum programa de bonificação por carcaça? Qual frigorífico?","Hoje a mistura é feita como — vagão misturador, ração pronta comprada, ou nada disso?"}'::text[], '{}'::text[], 'Cliente de cocho: recepção e pré-limpeza do grão, moagem em moinho de martelo, dosagem por pesagem, mistura e transporte até o vagão ou o cocho. Volume diário constante durante todo o período de confinamento — o dimensionamento é por t/h de pico, não por média mensal.', '{"MOINHO","MISTURADOR","TRANSPORTADOR","ELEVADOR","SILO","CAIXA","CACAMBA_PESAGEM","BALANCA","MOEGA","PRE_LIMPEZA","ENSACADEIRA"}'::text[], 'Confinamento de Angus e cruzado Angus e dieta de alto concentrado, todo dia, sem intervalo. Quem compra racao pronta nesse volume paga transporte de grao duas vezes. Moer e misturar dentro da fazenda encurta a logistica e da controle sobre o que entra na dieta e sobre a hora em que o cocho e abastecido. Acabamento e bonificacao dependem de genetica, dieta e manejo - nao sao entregues pelo equipamento.', '{"Não prometer marmoreio, acabamento, ganho de peso ou conversão alimentar como resultado do equipamento.","Não citar proporção fechada de concentrado/volumoso como se fosse regra da raça.","Não prometer prêmio ou bonificação de frigorífico.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'No confinamento a ração é o maior custo do senhor. Comprando pronta, o senhor paga o frete do grão para fora e da ração de volta. Com linha própria, o milho sai do silo, passa no moinho e vai para o cocho. A fórmula é a do seu nutricionista; a máquina garante que o lote de hoje seja igual ao de ontem.', 'Angus é gado de cocho. Aqui o assunto é linha de ração: moinho, misturador e transporte, dimensionados pelo número de cabeças em confinamento e pelos dias de trato. Fale de consistência da mistura e de logística de grão. Não prometa marmoreio nem conversão — isso é dieta e genética, não é a máquina.', 'Puro no Sul (RS, SC, PR); como pai de cruzamento industrial, forte em MS, MT, SP e Goiás.', 'angus', '🐂', 'aprovado', true, '{"Levantar com a engenharia a faixa de t/h recomendada por número de cabeças confinadas."}'::text[], '{"abcb-angus","embrapa-gado-corte","mapa-alimentacao-animal","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1020),
  ('brahman', 'Brahman', '{"Brâmane"}'::text[], 'bovinos', 'corte', 'raca', 'Zebuíno (Bos indicus), formado nos Estados Unidos a partir de Guzerá, Gir e Nelore', 'Corte — cria e produção de matrizes; base a pasto.', 'Zebuíno de bom desenvolvimento corporal e habilidade materna, adaptado ao clima tropical. Usado puro na cria e como aporte de rusticidade em cruzamentos e compostos, como o Brangus.', '{"pasto","semiconfinamento"}'::text[], '{"gado_corte","cria","recria","manutencao","proteica","semi_confinamento"}'::text[], 'cria', null, null, 'Animais de porte grande dentro dos zebuínos. Peso adulto varia com linhagem e manejo — não use número fechado em proposta.', 'Consumo de suplemento definido em formulação, com variação por categoria (vaca em cria, vaca solteira, bezerro em creep) e por época do ano. Use como referência apenas o que o técnico da fazenda estipulou.', null, '{}'::text[], '{"sal mineral","mineral proteico para vaca de cria","suplemento de recria"}'::text[], '{"farelada"}'::text[], '{"sal-comum","sal-mineral","calcario-calcitico","fosfato-bicalcico","nucleo-premix","ureia","farelo-soja","milho","farelo-algodao","caroco-algodao","concentrado-proteico"}'::text[], '{"A Branorte fornece equipamento para ração farelada e mistura mineral; não fornece peletizadora nem extrusora.","Formulação e níveis de garantia são responsabilidade do técnico do cliente."}'::text[], '{"Quantas matrizes o senhor tem em cria?","O senhor faz creep feeding no bezerro antes da desmama?","Quantas fórmulas diferentes de suplemento estão rodando hoje na fazenda?","Onde é feita a mistura hoje — comprada pronta, na revenda, ou na fazenda?","Tem estrutura de galpão e energia trifásica onde ficaria a mistura?"}'::text[], '{}'::text[], 'Perfil de mistura mineral e proteinada: pesagem, misturador horizontal e ensacamento. Se houver creep feeding para bezerro, entra moagem de grão em pequena escala.', '{"MISTURADOR","BALANCA","CACAMBA_PESAGEM","ENSACADEIRA","TRANSPORTADOR","MOEGA","SUPORTE_BAG","MOINHO"}'::text[], 'Rebanho de cria consome suplemento em regime contínuo e em várias fórmulas diferentes ao mesmo tempo — vaca em cria, novilha, bezerro no creep. Fazer a mistura na fazenda permite trocar de fórmula sem depender de pedido, prazo e frete de fornecedor.', '{"Não prometer peso à desmama, fertilidade ou índice reprodutivo por causa do equipamento.","Não afirmar superioridade da raça sobre outras em conversão ou ganho.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'Fazenda de cria roda três, quatro fórmulas diferentes ao mesmo tempo. Comprando pronto, cada troca é um pedido novo, prazo e frete. Com misturador na fazenda o senhor muda a fórmula no mesmo dia, do jeito que o técnico mandar.', 'Brahman é rebanho de cria a pasto. Foco em mineral e proteinado, mais creep feeding se ele suplementa bezerro. Equipamento: misturador horizontal com balança, ensacadeira se ele quiser estocar em saco. Pergunte quantas fórmulas ele roda ao mesmo tempo — isso define o tamanho do lote de mistura.', 'Centro-Oeste (MT, MS, GO) e Nordeste (BA, MA, PI).', 'brahman', '🐂', 'aprovado', true, '{"Confirmar se o cliente-tipo de Brahman demanda ensacadeira ou consome a granel no cocho."}'::text[], '{"abcz","embrapa-gado-corte","mapa-alimentacao-animal","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1030),
  ('brangus', 'Brangus', '{"Brangus Preto","Brangus Vermelho"}'::text[], 'bovinos', 'corte', 'composto', 'Composto taurino x zebuíno (base Angus + Brahman, proporções definidas pela associação de registro)', 'Corte — recria e terminação, com uso frequente em confinamento em região quente.', 'Composto que reúne a adaptação tropical do Brahman com a precocidade e o acabamento do Angus. Boa resposta em recria e terminação, com tolerância ao calor superior à do taurino puro.', '{"confinamento","semiconfinamento","pasto"}'::text[], '{"gado_corte","recria","engorda","semi_confinamento","confinamento"}'::text[], 'confinamento', null, null, 'Peso de abate conforme o programa comercial adotado; varia com grau de sangue e sistema.', 'Consumo e dias de cocho definidos pelo programa de terminação da fazenda. Não há faixa universal por ser composto com graus de sangue variáveis.', null, '{}'::text[], '{"ração de terminação","suplemento de recria","mineral proteico","sal mineral"}'::text[], '{"farelada"}'::text[], '{"milho","sorgo","farelo-soja","caroco-algodao","casquinha-soja","silagem-volumoso","calcario-calcitico","sal-mineral","nucleo-premix","ureia","bicarbonato-sodio","ddg-ddgs"}'::text[], '{"Racao FARELADA apenas; peletizacao exige processo adicional nao incluido.","A linha processa ingrediente seco. Silagem e volumoso umido nao passam por moinho nem por misturador - dimensionar somente o concentrado.","Grau de sangue e padrao racial sao definidos pela associacao de registro, nao pela Branorte."}'::text[], '{"Que parte do rebanho o senhor termina em cocho e que parte fica só no pasto?","Quantas cabeças por ciclo de terminação?","O senhor faz o mineral na fazenda ou compra pronto?","O grão da terminação é próprio ou comprado?","Qual a distância até o fornecedor de ração hoje, e qual o prazo de entrega dele?"}'::text[], '{}'::text[], 'Cliente que transita entre pasto e cocho: normalmente precisa das duas capacidades — mistura mineral em lote pequeno e linha de ração para a terminação. Dimensione pela fase de maior volume, que é a terminação.', '{"MOINHO","MISTURADOR","TRANSPORTADOR","ELEVADOR","SILO","CACAMBA_PESAGEM","BALANCA","MOEGA","CAIXA"}'::text[], 'Produtor de Brangus costuma terminar em cocho dentro de região quente, o que significa ração todo dia em época em que o frete de grão é mais caro. Linha própria de moagem e mistura resolve a dependência de entrega e permite ajustar a dieta ao lote que está no cocho.', '{"Não prometer ganho de peso, conversão ou acabamento por causa do equipamento.","Não afirmar proporção fixa de sangue Angus/Brahman sem citar a associação de registro.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'O senhor tem duas necessidades: o mineral do pasto e a ração do cocho. Dá para atender as duas com a mesma linha, dimensionando pelo pico, que é a terminação. Assim o senhor não fica com máquina parada seis meses por ano.', 'Brangus é o cliente que faz pasto e cocho. Levante os dois lados: quanto de mineral e quanto de ração de terminação. O equipamento de terminação é que manda no dimensionamento. Fale de rusticidade em cocho sem prometer índice — a genética é dele, a mistura é nossa.', 'Centro-Oeste, Sudeste e Sul, com expansão no Nordeste.', null, '🐂', 'aprovado', true, '{"Confirmar com a associação a faixa de graus de sangue aceita para registro antes de citar em material impresso."}'::text[], '{"abcz","abcb-angus","embrapa-gado-corte","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1040),
  ('senepol', 'Senepol', '{}'::text[], 'bovinos', 'corte', 'raca', 'Taurino adaptado (Bos taurus), sem giba, origem caribenha', 'Corte — cruzamento sobre zebuíno e terminação; forte mercado de sêmen.', 'Taurino sem giba, de pelo curto e boa tolerancia ao calor e a umidade. No Brasil, usado principalmente como raca paterna sobre matriz Nelore, com mercado ativo de semen. Desempenho de engorda e peso a desmama variam com sistema, manejo e grau de sangue do produto final - trate qualquer indice como dado do programa da fazenda, nao como caracteristica garantida da raca.', '{"pasto","semiconfinamento","confinamento"}'::text[], '{"gado_corte","recria","engorda","semi_confinamento","confinamento","proteica"}'::text[], 'semi_confinamento', null, null, 'Peso de abate depende do sistema e do momento de terminação escolhido pelo produtor.', 'Consumo e resposta a suplementação variam com o sistema e o grau de sangue do produto final. Trate qualquer índice de eficiência como dado do programa da fazenda, não como característica garantida.', null, '{}'::text[], '{"suplemento de recria","mineral proteico","ração de terminação"}'::text[], '{"farelada"}'::text[], '{"milho","sorgo","farelo-soja","caroco-algodao","silagem-volumoso","sal-mineral","calcario-calcitico","fosfato-bicalcico","nucleo-premix","ureia","concentrado-proteico"}'::text[], '{"Racao FARELADA; peletizacao exige processo adicional nao incluido.","A linha processa ingrediente seco. Silagem e outros volumosos umidos nao passam por moinho nem por misturador - dimensionar somente o concentrado.","A Branorte nao formula dieta nem participa de programa de avaliacao genetica."}'::text[], '{"O senhor trabalha com Senepol puro, produção de touro e sêmen, ou cruzamento sobre Nelore?","Tem lote em prova ou em confinamento de avaliação?","Como é feita a suplementação de pasto hoje — comprada ou misturada aqui?","O senhor termina em cocho ou vende para quem termina?","Quem acompanha a nutrição: técnico próprio, consultoria ou o fornecedor do núcleo?"}'::text[], '{}'::text[], 'Perfil misto: mistura mineral e proteinada para o pasto, mais linha de moagem e mistura quando há terminação. Produtor de genética costuma ter lote de touros em prova, que consome ração todo dia — vale perguntar.', '{"MOINHO","MISTURADOR","BALANCA","CACAMBA_PESAGEM","TRANSPORTADOR","ENSACADEIRA","MOEGA","SILO"}'::text[], 'Produtor que investe em genética costuma acompanhar de perto o que entra no cocho e cobra padronização da mistura. Produzir na fazenda dá rastreabilidade do que foi para cada lote e independência de fornecedor externo.', '{"Não usar ''bola da vez'', ''altamente adaptável a qualquer dieta'' ou qualquer superlativo de mercado.","Não prometer conversão alimentar, peso à desmama ou redução de dias de cocho.","Não afirmar superioridade de eficiência sobre outras raças sem fonte.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'O senhor mede desempenho de perto. Se a mistura varia de lote para lote, o dado que o senhor coleta perde valor. Maquina propria com pesagem repete a mesma formula lote apos lote, respeitados o tempo de mistura e a sequencia de carga, e o senhor sabe exatamente o que foi para cada piquete.', 'Senepol é público de genética: gente que compra sêmen, faz prova de touro e mede tudo. Argumento aqui é controle e padronização da mistura, não promessa de índice. Levante se ele tem lote em prova ou central — esse lote come ração todo dia.', 'Expansão nacional, com presença mais forte no Centro-Oeste e Sudeste.', 'senepol', '🐂', 'aprovado', true, '{"Definir com a engenharia a configuração mínima para atender fazenda de genética com lotes pequenos e fórmulas múltiplas."}'::text[], '{"embrapa-gado-corte","mapa-alimentacao-animal","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1050),
  ('canchim', 'Canchim', '{"Canchim Embrapa","MA (Charolês x Zebu, denominação de graus de sangue da associação)"}'::text[], 'bovinos', 'corte', 'composto', 'Composto de base Charolês x Zebu, desenvolvido pela Embrapa', 'Corte — recria, terminação e uso em cruzamento.', 'Composto nacional que reúne o potencial de crescimento e o rendimento de carcaça do Charolês com a rusticidade do zebuíno. Temperamento dócil e manejo fácil. Graus de sangue e padrão são definidos pela associação de registro.', '{"semiconfinamento","confinamento","pasto"}'::text[], '{"gado_corte","recria","engorda","semi_confinamento","confinamento"}'::text[], 'engorda', null, null, 'Animais de porte grande com bom rendimento de carcaça; peso de abate conforme o programa comercial.', 'Consumo definido pelo programa de recria e terminação da fazenda. Sem faixa universal.', null, '{}'::text[], '{"suplemento de recria","ração de terminação","mineral proteico","sal mineral"}'::text[], '{"farelada"}'::text[], '{"milho","sorgo","farelo-soja","caroco-algodao","silagem-volumoso","casquinha-soja","calcario-calcitico","sal-mineral","nucleo-premix","ureia","polpa-citrica"}'::text[], '{"Ração FARELADA; peletização exige processo adicional não incluído.","Volumoso (silagem, feno) não é processado pela linha de ração — dimensionar apenas o que passa por moinho e misturador."}'::text[], '{"O senhor faz recria, terminação ou os dois?","Produz o grão na propriedade? Que volume por safra?","Usa silagem como volumoso? Em que proporção da dieta?","Quantas cabeças no cocho por ciclo?","Onde ficaria a linha de ração — tem galpão, energia e acesso para caminhão?"}'::text[], '{}'::text[], 'Cliente de recria e terminação: moagem de grão, dosagem por pesagem, mistura e transporte para cocho. Silagem entra como volumoso e não passa pela linha de ração — atenção para não superdimensionar por causa dela.', '{"MOINHO","MISTURADOR","TRANSPORTADOR","ELEVADOR","SILO","CACAMBA_PESAGEM","BALANCA","MOEGA"}'::text[], 'Recria e terminação de Canchim rodam dieta energética por período longo. Quem produz o próprio grão e ainda compra ração pronta está pagando frete nos dois sentidos. Linha de moagem e mistura na fazenda encurta esse caminho.', '{"Não prometer ganho de peso, rendimento de carcaça ou conversão como efeito do equipamento.","Não citar fração fixa de sangue Charolês/Zebu sem referenciar a associação.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'O senhor já colhe o milho aqui. Hoje ele sai para a fábrica e volta como ração, com frete nos dois sentidos. Com moinho e misturador, o grão vai direto do silo para o cocho. A silagem continua sendo tratada à parte, como sempre foi.', 'Canchim é gado de recria e cocho, raça nacional feita pela Embrapa. Cliente típico já produz milho ou silagem. Foque em moinho e misturador dimensionados pelo lote de terminação. Silagem não passa pelo moinho — não some ela na conta de capacidade.', 'Sudeste (com origem em São Paulo) e Centro-Oeste.', 'canchim', '🐂', 'aprovado', true, '{"Confirmar denominação oficial dos graus de sangue junto à associação antes de imprimir."}'::text[], '{"abccan","embrapa-gado-corte","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1060),
  ('tabapua', 'Tabapuã', '{"Tabapuã Mocho"}'::text[], 'bovinos', 'corte', 'raca', 'Zebuíno (Bos indicus) brasileiro, formado a partir de Nelore, Gir e Guzerá', 'Corte — cria e engorda; usado também para melhorar acabamento de rebanho zebuíno.', 'Zebuíno brasileiro de porte grande, pelo claro e curto, temperamento dócil e boa habilidade materna. Engorda tanto a pasto quanto no cocho, com bom acabamento de carcaça para um zebuíno.', '{"pasto","semiconfinamento","confinamento"}'::text[], '{"gado_corte","cria","recria","engorda","proteica","semi_confinamento","confinamento","manutencao"}'::text[], 'recria', null, null, 'Porte grande dentro dos zebuínos; peso adulto e de abate variam com linhagem e manejo.', 'Consumo definido pela formulação e pelo sistema adotado. Por ser raça versátil entre pasto e cocho, o perfil de consumo muda muito de fazenda para fazenda — levante caso a caso.', null, '{}'::text[], '{"sal mineral","mineral proteico","suplemento de recria","ração de terminação"}'::text[], '{"farelada"}'::text[], '{"sal-comum","sal-mineral","calcario-calcitico","fosfato-bicalcico","nucleo-premix","ureia","milho","sorgo","farelo-soja","caroco-algodao","farelo-algodao","silagem-volumoso"}'::text[], '{"Racao FARELADA; peletizacao exige processo adicional nao incluido.","A linha processa ingrediente seco. Silagem e volumoso umido nao passam por moinho nem por misturador - dimensionar somente o concentrado.","Formulacao e do tecnico do cliente."}'::text[], '{"Hoje o senhor engorda mais no pasto ou no cocho?","Isso muda de ano para ano conforme o preço da arroba?","Quanto o senhor gasta hoje por mês com mineral e proteinado prontos?","Se fizesse ração, teria grão próprio ou compraria?","O senhor pretende começar pequeno e crescer depois, ou já montar tudo?"}'::text[], '{}'::text[], 'Cliente que costuma precisar dos dois produtos: mistura mineral e proteinada para o pasto, e ração farelada quando entra no cocho. Configuração modular funciona bem aqui — misturador e balança primeiro, moinho depois se ele intensificar.', '{"MISTURADOR","BALANCA","CACAMBA_PESAGEM","ENSACADEIRA","MOINHO","TRANSPORTADOR","MOEGA","SUPORTE_BAG"}'::text[], 'É um rebanho que transita entre pasto e cocho conforme o preço da arroba. Ter mistura própria dá flexibilidade de mudar de estratégia sem depender de pedido e prazo de fornecedor a cada virada de mercado.', '{"Não prometer acabamento de carcaça, ganho de peso ou precocidade por causa do equipamento.","Não afirmar superioridade da raça sobre outros zebuínos.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'O senhor muda de estratégia conforme o ano — às vezes segura no pasto, às vezes coloca no cocho. Começando pelo misturador com balança, o senhor já resolve o mineral e o proteinado. Se depois quiser fazer ração, acrescenta o moinho na mesma linha.', 'Tabapuã é zebuíno versátil: engorda no pasto ou no cocho. Cliente equilibrado entre proteinado e ração. Comece pelo misturador com balança, que atende o mineral, e deixe o moinho como próximo passo se ele intensificar. Venda em módulo, não empurre linha completa de saída.', 'Sudeste, Centro-Oeste e Nordeste.', null, '🐂', 'aprovado', true, '{"Foto do Tabapuã reprovada/ausente na auditoria — buscar imagem com licença compatível.","Validar proposta modular (misturador primeiro, moinho depois) com a engenharia."}'::text[], '{"abcz","embrapa-gado-corte","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1070),
  ('guzera', 'Guzerá', '{"Guzerat","Kankrej (origem indiana)"}'::text[], 'bovinos', 'corte', 'raca', 'Zebuíno (Bos indicus) de dupla aptidão', 'Corte e leite — cria, cruzamento e ordenha a pasto no semiárido.', 'Zebuíno rústico e longevo, com boa habilidade materna e produção de leite razoável. Dupla aptidão: entra tanto em rebanho de corte quanto em ordenha a pasto, e é base de linhagens formadas no Brasil.', '{"pasto","semiconfinamento"}'::text[], '{"gado_corte","gado_leite","cria","recria","manutencao","proteica","semi_confinamento"}'::text[], 'cria', null, null, 'Animal longevo, de porte médio a grande. Produção de leite existe mas é secundária em rebanho de corte — não use média de litros sem confirmar o rebanho do cliente.', 'No semiárido o consumo de suplemento oscila muito entre seca e chuva. Trate qualquer faixa como referência da fazenda; o número que vale é o do programa nutricional local.', null, '{}'::text[], '{"sal mineral","mineral proteico de seca","concentrado leiteiro leve para vaca em ordenha","volumoso conservado"}'::text[], '{"farelada"}'::text[], '{"sal-comum","sal-mineral","calcario-calcitico","fosfato-bicalcico","nucleo-premix","ureia","milho","sorgo","milheto","palma-forrageira","farelo-soja","farelo-algodao","caroco-algodao","feno","melaco"}'::text[], '{"Racao FARELADA e mistura mineral; sem peletizacao ou extrusao.","Palma, silagem e outros volumosos umidos nao passam por moinho de martelo convencional - verificar com a engenharia antes de prometer processamento.","Melaco e ingrediente liquido: exige sistema de dosagem especifico e nao entra na mistura seca sem consulta previa a engenharia."}'::text[], '{"Seu rebanho é só de corte ou o senhor ordenha alguma parte?","Que matéria-prima o senhor consegue comprar aqui perto — sorgo, milheto, caroço de algodão, palma?","De onde vem hoje o mineral e o proteinado, e qual o frete?","Como o senhor atravessa a seca: proteinado, volumoso conservado, palma?","Tem energia trifásica e galpão disponível onde ficaria a mistura?"}'::text[], '{}'::text[], 'Suplementação mineral e proteica de seca: pesagem, mistura e ensacamento. Onde há palma, sorgo ou milheto da própria região, o moinho ganha importância porque o cliente processa matéria-prima local em vez de comprar grão de fora.', '{"MISTURADOR","BALANCA","CACAMBA_PESAGEM","ENSACADEIRA","MOINHO","TRANSPORTADOR","MOEGA","SUPORTE_BAG"}'::text[], 'No semiárido o custo do suplemento pronto carrega frete longo. Quem tem matéria-prima regional — sorgo, milheto, palma, caroço de algodão — aproveita melhor comprando ingrediente e misturando na fazenda do que comprando produto acabado que veio de longe.', '{"Não prometer litros de leite, peso à desmama ou desempenho na seca por causa do equipamento.","Não citar média de produção leiteira da raça sem confirmar a fonte e o rebanho.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'O saco de suplemento que chega aqui vem de longe, e o senhor paga esse caminho. Se o senhor já tem sorgo, milheto ou caroço de algodão na região, dá para comprar o ingrediente perto e fazer a mistura na fazenda. A fórmula continua sendo a do técnico.', 'Guzerá é rebanho de semiárido, dupla aptidão. O ponto forte aqui é matéria-prima regional: sorgo, milheto, palma, caroço de algodão. Misturador com balança para o mineral, moinho se ele processar grão local. Levante a distância até o fornecedor atual — o frete costuma ser o maior argumento.', 'Nordeste e semiárido, Minas Gerais e Centro-Oeste.', 'guzera', '🐂', 'aprovado', true, '{"Confirmar com a engenharia o que a linha processa e o que não processa entre as matérias-primas do semiárido (palma, casca de algodão, feno)."}'::text[], '{"abcz","embrapa-semiarido","embrapa-gado-corte","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1080),
  ('cruzamento-industrial', 'Cruzamento Industrial (F1 taurino x Nelore)', '{"F1 Angus x Nelore","meio-sangue","cruza industrial","novilho precoce"}'::text[], 'bovinos', 'corte', 'cruzamento', 'Cruzamento industrial — touro taurino (Angus, Senepol e outros) sobre matriz Nelore', 'Corte — produção de novilho precoce para terminação em confinamento ou semiconfinamento.', 'Cruzamento de touro taurino sobre matriz zebuina para explorar a heterose: mais precocidade e melhor acabamento mantendo parte da rusticidade da mae. O produto comercial e o animal de abate, e nao a formacao de uma raca - o destino da femea F1 varia com o esquema de cruzamento adotado pela fazenda.', '{"confinamento","semiconfinamento","pasto"}'::text[], '{"gado_corte","recria","engorda","semi_confinamento","confinamento","proteica"}'::text[], 'confinamento', null, null, 'Abate jovem, com peso definido pela exigência do frigorífico ou do programa de novilho precoce que o produtor atende.', 'Dias de cocho e consumo diário variam com o peso de entrada e com a meta de acabamento do programa. Abate precoce encurta o período de cocho em relação a programas de terminação longa. Números concretos só com o nutricionista do cliente.', null, '{}'::text[], '{"ração de terminação","suplemento de recria","proteico-energético de pasto","sal mineral"}'::text[], '{"farelada"}'::text[], '{"milho","sorgo","farelo-soja","caroco-algodao","casquinha-soja","silagem-volumoso","ddg-ddgs","polpa-citrica","calcario-calcitico","sal-mineral","nucleo-premix","ureia","bicarbonato-sodio","adsorvente-micotoxinas"}'::text[], '{"Ração FARELADA; peletização exige processo adicional não incluído.","Dieta de alto concentrado exige acompanhamento de nutricionista — a Branorte não formula dieta.","Volumoso não passa pela linha de ração; dimensionar somente concentrado."}'::text[], '{"O senhor produz o F1 na fazenda ou compra o bezerro cruzado para terminar?","Quantos ciclos de cocho por ano, e quantas cabeças por ciclo?","Qual o pico de ração por dia no cocho cheio?","O grão é próprio ou comprado? Tem silo na fazenda?","Já teve problema de atraso ou falta de entrega de ração no meio do ciclo?"}'::text[], '{}'::text[], 'Linha de ração completa para confinamento: recepção e pré-limpeza, moagem, dosagem por pesagem, mistura e transporte para vagão ou cocho. Ciclo curto e alta rotatividade de lote — a linha precisa dar conta do pico diário, com folga para entrada de lote novo.', '{"MOINHO","MISTURADOR","TRANSPORTADOR","ELEVADOR","SILO","CAIXA","CACAMBA_PESAGEM","BALANCA","MOEGA","PRE_LIMPEZA"}'::text[], 'Cruzamento industrial é volume de ração concentrado em janela curta. O produtor entra e sai do cocho rápido e repete o ciclo. Nesse regime, depender de entrega externa de ração significa parar o cocho quando o caminhão atrasa. Linha própria elimina esse risco de abastecimento.', '{"Não prometer heterose, precocidade, acabamento, conversão ou dias de cocho como resultado do equipamento.","Não usar ''maior ticket de ração'' nem qualquer comparação superlativa entre públicos.","Não prometer prêmio de programa de novilho precoce ou bonificação de frigorífico.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'O senhor tem um giro rápido: enche o cocho, termina e repete. Se o caminhão de ração atrasa, o lote perde ritmo e o senhor não recupera. Com moinho e misturador aqui dentro, o abastecimento passa a depender do senhor e do seu silo, não da agenda da fábrica.', 'Aqui o cliente compra novilho ou produz o F1 para terminar rápido. É volume de ração em janela curta, com vários ciclos por ano. Dimensione pelo pico diário, não pela média. Argumento é abastecimento e logística de grão — nunca prometa dias de cocho ou acabamento.', 'Centro-Oeste, Sudeste e Sul, junto aos confinamentos comerciais e aos programas de novilho precoce.', null, '🐂', 'aprovado', true, '{"Buscar foto própria de F1 em confinamento — a imagem ''confinamento'' do acervo é de um touro Wagyu e não serve aqui.","Definir com a engenharia a tabela de t/h por cabeça confinada para uso em proposta."}'::text[], '{"embrapa-gado-corte","abcz","abcb-angus","mapa-alimentacao-animal","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1090),
  ('wagyu', 'Wagyu', '{"Japanese Black","Kuroge Washu","Wagyu cruzado (sobre Angus ou Nelore)"}'::text[], 'bovinos', 'corte', 'raca', 'Taurino (Bos taurus) de origem japonesa', 'Corte premium — terminação longa em confinamento, atendendo programa de carne com classificação de marmoreio.', 'Taurino japonês selecionado para deposição de marmoreio intenso, criado em programas de carne premium. Ciclo de terminação bem mais longo que o do gado comercial, com período de cocho prolongado. No Brasil aparece puro e em cruzamento.', '{"confinamento"}'::text[], '{"gado_corte","recria","engorda","confinamento"}'::text[], 'confinamento', null, null, 'Peso de abate e idade seguem o protocolo do programa premium, não o padrão do gado comercial.', 'O período de cocho é substancialmente mais longo que o do gado comercial e a dieta é dividida em fases pelo programa. Duração e consumo são definidos pelo protocolo do programa de carne que o cliente atende — não estime.', null, '{}'::text[], '{"ração de terminação longa","dieta de acabamento de alto concentrado","sal mineral"}'::text[], '{"farelada"}'::text[], '{"milho","sorgo","farelo-soja","farelo-trigo","farelo-arroz","quirera-arroz","casquinha-soja","silagem-volumoso","feno","calcario-calcitico","sal-mineral","nucleo-premix","bicarbonato-sodio","oleo-gordura","adsorvente-micotoxinas"}'::text[], '{"Racao FARELADA; peletizacao exige processo adicional nao incluido.","A linha processa ingrediente seco. Silagem e feno nao passam por moinho nem por misturador - dimensionar somente o concentrado.","Oleo e gordura sao liquidos: so entram com sistema de dosagem especifico, a confirmar com a engenharia.","Dieta de programa premium e definida pelo protocolo e pelo nutricionista - a Branorte nao formula nem valida dieta.","Rebanho pequeno pode nao justificar linha grande: dimensionar pela formula de menor lote, nao pelo pico teorico."}'::text[], '{"O senhor trabalha com Wagyu puro ou cruzado? Sobre qual base?","Que programa de carne o senhor atende, e ele define o protocolo de dieta?","Quantos dias de cocho no seu programa, e quantas fases de fórmula?","Quantos animais em cocho ao mesmo tempo?","Hoje quem faz a ração — fábrica terceirizada, vagão misturador ou compra pronta?"}'::text[], '{}'::text[], 'Linha de ração com forte exigência de precisão: o programa costuma trabalhar com várias fórmulas ao longo do período de cocho. Pesagem confiável e mistura homogênea pesam mais que capacidade bruta — o rebanho é menor, mas o custo por animal é alto e a dieta muda de fase.', '{"MOINHO","MISTURADOR","TRANSPORTADOR","ELEVADOR","SILO","CAIXA","CACAMBA_PESAGEM","BALANCA","MOEGA","PRE_LIMPEZA","ENSACADEIRA"}'::text[], 'Wagyu passa muito mais tempo no cocho que o gado comercial, e o programa exige troca de fórmula por fase. Ter a linha na fazenda permite mudar de fórmula no dia certo e registrar o que foi para cada lote, sem depender de pedido mínimo de fábrica para um rebanho pequeno.', '{"Não prometer marmoreio, nota de classificação de carcaça ou aprovação em programa premium.","Não prometer ganho de peso, conversão ou redução de dias de cocho.","Não usar ''maior ticket de ração'' nem comparação superlativa com outros públicos.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'O senhor tem poucos animais e cada um vale muito, e o programa manda trocar a fórmula ao longo do cocho. Comprar isso pronto esbarra em pedido mínimo de fábrica. Com a linha aqui, o senhor faz o lote do tamanho que precisa, na hora certa, e sabe exatamente o que entrou nele.', 'Wagyu é programa premium: cocho longo, fórmula que muda por fase, rebanho pequeno e caro. Aqui não venda capacidade — venda precisão de pesagem, homogeneidade e a possibilidade de rodar lote pequeno de fórmula específica. Nunca prometa marmoreio ou classificação de carcaça.', 'Confinamentos e programas de carne premium no Centro-Oeste, Sudeste e Sul.', 'confinamento', '🐂', 'aprovado', true, '{"Confirmar com a engenharia a menor configuração viável de linha para lote pequeno com troca frequente de fórmula.","Validar se há restrição de precisão de balança exigida por programas de carne premium."}'::text[], '{"embrapa-gado-corte","mapa-alimentacao-animal","branorte-catalogo","branorte-engenharia"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1100),
  ('girolando', 'Girolando', '{"Giro","Holandês x Gir","Girolando 5/8"}'::text[], 'bovinos', 'leite', 'composto', 'Composto Holandês x Gir (raça brasileira registrada)', 'Leite comercial', 'Raça brasileira registrada, formada pelo cruzamento Holandês x Gir. Não se resume a um único grau de sangue: a associação da raça admite diferentes graus de sangue e é ela que define o padrão, o registro e o enquadramento de cada animal — consultar o regulamento da associação, edição vigente, antes de citar grau em proposta. Junta produção leiteira do Holandês com adaptação tropical do Gir. Girolando é o recorte REGISTRADO; vaca de cruzamento Holandês x zebu sem registro entra no card de mestiças. Os dois recortes se confundem no campo — muita vaca chamada de girolando não tem registro — e por isso não se somam. Juntos formam a maior parte do leite nacional; separadamente, não há número validado.', '{"pasto","semiconfinamento","confinamento"}'::text[], '{"gado_leite","cria","recria","manutencao","semi_confinamento","confinamento"}'::text[], 'gado_leite', null, null, 'Porte intermediário entre Holandês e Gir; o peso adulto acompanha o grau de sangue. Confirmar com o produtor, não estimar.', 'Produção varia com grau de sangue, volumoso disponível, manejo e ambiente. Faixas de 15 a 30 L/vaca/dia aparecem em rebanhos bem manejados — é referência de conversa, não meta. O número do rebanho do cliente sai do controle leiteiro dele. Para dimensionar a fábrica, use: nº de vacas em lactação x kg de concentrado/vaca/dia informado pelo nutricionista.', null, '{}'::text[], '{"Concentrado no cocho da ordenha","Concentrado no cocho do lote","Suplementação mineral e proteica a pasto"}'::text[], '{"farelada"}'::text[], '{"milho","sorgo","farelo-soja","caroco-algodao","farelo-algodao","polpa-citrica","casquinha-soja","farelo-trigo","calcario-calcitico","fosfato-bicalcico","sal-comum","sal-mineral","nucleo-premix","ureia","adsorvente-micotoxinas"}'::text[], '{"A Branorte fornece equipamentos para produção de ração FARELADA; peletização exige processo adicional não incluído.","Volumoso (silagem, pasto, cana) fica fora da fábrica — a fábrica faz o concentrado.","TMR/dieta completa é vagão misturador, não é escopo da fábrica."}'::text[], '{"Qual o grau de sangue predominante do rebanho e quantas vacas estão em lactação hoje?","O concentrado é comprado pronto, ou o senhor já mistura alguma coisa na fazenda?","A ração é fornecida no cocho da ordenha ou no cocho do lote?","Os lotes são separados por faixa de produção?","Quem formula a dieta: nutricionista próprio, da cooperativa ou da revenda?"}'::text[], '{}'::text[], 'Moagem de milho ou sorgo, dosagem e mistura com farelos, núcleo e minerais — sai concentrado ensacado ou a granel. Dieta completa (TMR) não é feita na fábrica: misturar silagem com concentrado é trabalho de vagão misturador, equipamento separado.', '{"MOINHO","MISTURADOR","TRANSPORTADOR","ELEVADOR","MOEGA","CAIXA","BALANCA","ENSACADEIRA","SILO"}'::text[], 'Rebanho Girolando aparece em pasto, semiconfinamento e confinamento — em todos, o concentrado pode ser produzido dentro da fazenda. A fábrica Branorte moe, dosa e mistura o concentrado a partir do milho e dos farelos que o produtor já compra ou já colhe.', '{"Não prometer litros/dia, pico de lactação ou persistência como resultado do equipamento.","Não citar percentual do leite nacional atribuído à raça.","Não fechar a raça em um único grau de sangue (5/8) — a associação reconhece uma faixa.","Não oferecer ração peletizada.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'O senhor tem quantas vacas na ordenha hoje? A fábrica aqui faz o CONCENTRADO — pega o seu milho, moe, dosa com o farelo e o núcleo e entrega pronto pro cocho. A silagem continua sendo silagem: ela não entra na fábrica. Se o senhor quiser tudo misturado junto, isso é vagão, é outro equipamento. O que a fábrica muda é que o senhor passa a fazer o concentrado com o preço do seu milho, em vez de comprar saco pronto.', 'Girolando é raça registrada, com grau de sangue variável — quem define o padrão e o registro é a associação da raça. Quanto mais sangue holandês e mais litro no tanque, mais concentrado por vaca. A Branorte entrega a fábrica que faz esse concentrado dentro da porteira: moinho, misturador, dosagem e ensaque. Volumoso não passa aqui.', 'Minas Gerais, Goiás, Sudeste e presença em todo o país.', 'girolando', '🐄', 'aprovado', true, '{"Confirmar os graus de sangue e o padrão vigente no regulamento da associação antes de citar em proposta.","Faixa de litros/dia é referência de campo — validar com o controle leiteiro do cliente."}'::text[], '{"girolando","embrapa-gado-leite","branorte-catalogo","branorte-engenharia"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1110),
  ('holandes', 'Holandês (Holstein)', '{"Holstein","HPB","preto e branco"}'::text[], 'bovinos', 'leite', 'raca', 'Taurino (Bos taurus)', 'Leite comercial de alta produção', 'Taurino de grande porte, dócil, usado nas bacias leiteiras tecnificadas e em sistemas confinados. Exigência nutricional por animal mais alta que a de zebuínos e mestiços: dieta de alta energia e proteína ao longo de toda a lactação. Pouco tolerante ao calor e a parasitas — depende de conforto térmico e manejo intensivo.', '{"free_stall","semiconfinamento"}'::text[], '{"gado_leite","recria","cria","manutencao","confinamento","semi_confinamento"}'::text[], 'gado_leite', null, null, 'Animal de grande porte. Peso adulto e consumo de matéria seca devem vir da ficha do rebanho, não de estimativa.', 'Faixas de referência citadas em campo ficam em torno de 25 a 30 L/vaca/dia, e de 6.000 a 10.000 kg por lactação de 305 dias. Depende de genética, ambiente, qualidade do volumoso e manejo — não é resultado do equipamento. O número do rebanho sai do controle leiteiro do cliente. Para dimensionar: nº de vacas em lactação x kg de concentrado/vaca/dia da formulação.', null, '{}'::text[], '{"Concentrado dosado por faixa de produção","Concentrado incorporado à dieta completa por vagão misturador"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","caroco-algodao","farelo-trigo","polpa-citrica","ddg-ddgs","casquinha-soja","calcario-calcitico","fosfato-bicalcico","bicarbonato-sodio","sal-comum","nucleo-premix","adsorvente-micotoxinas"}'::text[], '{"A Branorte fornece equipamentos para produção de ração FARELADA; peletização exige processo adicional não incluído.","Volumoso não entra na fábrica.","Dieta completa (TMR) é vagão misturador — equipamento separado, fora do escopo."}'::text[], '{"Quantas vacas em lactação e em quantos lotes de produção?","Hoje o concentrado é comprado pronto, ou já existe alguma mistura na fazenda?","Já usa vagão misturador para dieta completa? De que capacidade?","Qual o volume mensal de concentrado consumido hoje?","Tem estrutura de armazenagem de milho na propriedade ou compra em saco?"}'::text[], '{}'::text[], 'Moagem, dosagem e mistura do concentrado (farelada). Em free-stall o concentrado normalmente segue para o vagão misturador, que junta com a silagem e monta a dieta completa. A fábrica entrega o concentrado pronto e uniforme; o vagão faz a mistura final.', '{"MOINHO","MISTURADOR","TRANSPORTADOR","ELEVADOR","MOEGA","SILO","CACAMBA_PESAGEM","BALANCA","ENSACADEIRA","PRE_LIMPEZA"}'::text[], 'Rebanho de alto consumo de concentrado por cabeça, com exigência de energia e proteína elevada ao longo de toda a lactação. Onde há free-stall ou confinamento, o volume diário de concentrado é constante o ano todo — cenário em que produzir o concentrado dentro da fazenda pode mexer no custo do concentrado. A Branorte entrega a fábrica que moe e mistura esse concentrado; o resultado no custo depende da formulação, do preço do grão e do manejo do cliente.', '{"Não prometer litros/dia, pico ou persistência de lactação como resultado do equipamento.","Não afirmar que é ''a raça que mais exige ração'' — descrever a exigência tecnicamente.","Não vender a fábrica como substituta do vagão misturador.","Não oferecer ração peletizada.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'Em free-stall o cocho não pode falhar nenhum dia. A fábrica aqui garante o concentrado sempre igual, feito com o seu milho, na quantidade que o seu nutricionista mandar. Ela não substitui o vagão: o vagão continua juntando a silagem com o concentrado. O que muda é de onde vem o concentrado — em vez de caminhão de fora, sai do seu galpão.', 'Holandês é vaca de cocho cheio: alta exigência de energia e proteína, o ano inteiro, com lote grande e consumo previsível. A fábrica Branorte faz o concentrado dentro da fazenda a partir do milho e dos farelos. A dieta completa continua sendo trabalho do vagão misturador.', 'Sul (RS, SC, PR), regiões de clima ameno e bacias leiteiras tecnificadas.', 'holandes', '🐄', 'aprovado', true, '{"Faixas de litros/dia e kg por lactação são referência — validar com o controle leiteiro do cliente antes de usar em proposta."}'::text[], '{"embrapa-gado-leite","branorte-catalogo","branorte-engenharia","mapa-alimentacao-animal"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1120),
  ('gir-leiteiro', 'Gir Leiteiro', '{"Gir de leite","Gir"}'::text[], 'bovinos', 'leite', 'raca', 'Zebuíno (Bos indicus)', 'Leite a pasto no trópico e produção de touros/sêmen para Girolando', 'Zebuíno leiteiro adaptado ao trópico: tolera calor, resiste a ectoparasitas e tem boa longevidade. É a base materna do Girolando e fornece touros e sêmen para esse cruzamento. Produz a pasto com menor exigência de concentrado que o Holandês.', '{"pasto","semiconfinamento"}'::text[], '{"gado_leite","cria","recria","manutencao","proteica","semi_confinamento"}'::text[], 'gado_leite', null, null, 'Porte menor que o do Holandês. Peso adulto deve ser confirmado com o produtor.', 'Faixas citadas em campo ficam em torno de 10 a 12 L/vaca/dia, com médias próximas de 3.600 kg em lactação de 305 dias. Varia com manejo, pasto e ambiente — é referência de conversa. O número do rebanho vem do controle leiteiro do cliente e dos registros da associação. Dimensionamento: nº de vacas em lactação x kg de concentrado/vaca/dia da formulação.', null, '{}'::text[], '{"Concentrado no cocho da ordenha","Suplemento mineral e proteico a pasto"}'::text[], '{"farelada"}'::text[], '{"milho","sorgo","farelo-soja","farelo-algodao","caroco-algodao","farelo-arroz","calcario-calcitico","fosfato-bicalcico","sal-comum","sal-mineral","nucleo-premix","ureia"}'::text[], '{"A Branorte fornece equipamentos para produção de ração FARELADA; peletização exige processo adicional não incluído.","Pasto, cana e silagem ficam fora da fábrica.","Dieta completa (TMR) é vagão misturador."}'::text[], '{"Quantas vacas em ordenha e qual a média do tanque hoje?","Vende touro ou sêmen para produtores de Girolando?","O concentrado é comprado pronto ou o senhor já mistura o milho da fazenda?","Fornece suplemento mineral proteico a pasto no período seco?","Tem milho próprio ou compra? Em saco ou a granel?"}'::text[], '{}'::text[], 'Moagem de milho ou sorgo e mistura com farelos, núcleo e minerais — concentrado farelado e suplemento mineral/proteico. Pasto, cana e silagem não passam pela fábrica.', '{"MOINHO","MISTURADOR","TRANSPORTADOR","MOEGA","CAIXA","BALANCA","ENSACADEIRA","SUPORTE_BAG"}'::text[], 'Rebanho que trabalha a pasto e usa concentrado ajustado à produção, não dieta de alta densidade o ano todo. A fábrica atende bem esse perfil: moe o milho da própria fazenda e mistura concentrado e suplemento mineral sem depender de saco comprado.', '{"Não prometer litros/dia como resultado do equipamento.","Não prometer ganho de produção por troca de concentrado.","Não oferecer ração peletizada.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'Seu gado tira leite no pasto, então o concentrado entra pra completar, não pra substituir o pasto. A fábrica aqui moe o seu milho e mistura com o farelo e o núcleo — o senhor faz o concentrado e o mineral aí mesmo. Cana e capim continuam fora disso; a fábrica é pro grão.', 'Gir leiteiro produz no calor, a pasto, com concentrado moderado. É rebanho de fazenda que já tem milho. A fábrica Branorte moe e mistura o concentrado e o suplemento na propriedade. Pasto e volumoso ficam fora da fábrica.', 'Minas Gerais, Nordeste e regiões quentes.', 'gir-leiteiro', '🐄', 'aprovado', true, '{"Faixa de litros/dia e média por lactação são referência — validar com controle leiteiro e registros da associação."}'::text[], '{"abcz","embrapa-gado-leite","embrapa-semiarido","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1130),
  ('jersey', 'Jersey', '{"Jersey","Jersolando (em cruzamento)"}'::text[], 'bovinos', 'leite', 'raca', 'Taurino (Bos taurus)', 'Leite para indústria de derivados; cruzamento com Holandês', 'Taurino de porte pequeno, com leite de teor de gordura e proteína mais alto que o do Holandês — o que interessa a quem entrega para queijo e derivados. Consome menos matéria seca por animal que o Holandês e é bastante usada em cruzamento com ele.', '{"semiconfinamento","confinamento","pasto"}'::text[], '{"gado_leite","recria","cria","manutencao","semi_confinamento","confinamento"}'::text[], 'gado_leite', null, null, 'Porte pequeno, menor consumo de matéria seca por animal que o Holandês. Confirmar peso e consumo com a ficha do rebanho.', 'Faixas de referência citadas em campo: 15 a 20 L/vaca/dia, com teores de gordura e proteína acima dos do Holandês. Os teores reais do rebanho saem da análise do tanque do cliente — use o laudo dele, não número de tabela. Dimensionamento da fábrica: nº de vacas em lactação x kg de concentrado/vaca/dia da formulação.', null, '{}'::text[], '{"Concentrado no cocho da ordenha","Concentrado incorporado à dieta completa por vagão misturador"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","polpa-citrica","caroco-algodao","farelo-trigo","casquinha-soja","calcario-calcitico","fosfato-bicalcico","bicarbonato-sodio","sal-comum","nucleo-premix"}'::text[], '{"A Branorte fornece equipamentos para produção de ração FARELADA; peletização exige processo adicional não incluído.","Volumoso não entra na fábrica.","Dieta completa (TMR) é vagão misturador."}'::text[], '{"Quantas vacas em lactação e o leite vai para queijo ou para tanque comum?","Recebe bonificação por gordura e proteína na sua indústria?","Tem laudo de análise do tanque recente?","Trabalha com Jersey puro ou em cruzamento com Holandês?","O concentrado é comprado pronto ou já mistura na propriedade?"}'::text[], '{}'::text[], 'Moagem, dosagem e mistura do concentrado farelado. Uniformidade de mistura importa: minerais e núcleo em baixa inclusão precisam ficar distribuídos. Volumoso e dieta completa ficam fora — TMR é vagão misturador.', '{"MOINHO","MISTURADOR","TRANSPORTADOR","MOEGA","CAIXA","BALANCA","CACAMBA_PESAGEM","ENSACADEIRA"}'::text[], 'Cliente que vende sólidos, não litro. A dieta precisa ser equilibrada em proteína e minerais, e núcleo e mineral entram em baixa inclusão — mistura mal feita entrega fórmula diferente de saco para saco. A fábrica Branorte entrega concentrado homogêneo, dosado e repetível, feito com o grão da propriedade. O teor de sólidos do tanque continua dependendo de genética, dieta formulada e manejo.', '{"Não prometer teor de gordura, proteína ou litros como resultado do equipamento.","Não usar percentuais de sólidos como garantia — são referência, o laudo do tanque é a fonte.","Não oferecer ração peletizada.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'O senhor não vende litro, vende sólido — então o que conta é a dieta bater certo todo dia. A fábrica aqui moe e mistura o concentrado na fazenda, com a mesma fórmula sempre, sem variar de saco pra saco. A silagem continua fora: ela vai no vagão, não na fábrica.', 'Jersey é vaca pequena que entrega leite mais rico em sólidos, boa para quem vende pra queijo. Come menos que o Holandês, mas a dieta tem que ser bem equilibrada. A fábrica Branorte faz o concentrado com mistura uniforme dentro da fazenda. Volumoso segue por fora.', 'Sul e Sudeste, e em cruzamento em várias bacias leiteiras.', 'jersey', '🐄', 'aprovado', true, '{"Faixas de litros/dia e de teores de sólidos são referência — confirmar com o laudo do tanque do cliente."}'::text[], '{"embrapa-gado-leite","branorte-catalogo","branorte-engenharia"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1140),
  ('pardo-suico', 'Pardo-Suíço (Brown Swiss)', '{"Brown Swiss","Pardo Suíço","Pardo"}'::text[], 'bovinos', 'leite', 'raca', 'Taurino (Bos taurus) de dupla aptidão', 'Leite e dupla aptidão; usada em cruzamentos', 'Taurino de dupla aptidão: leite com bom teor de sólidos e também aproveitamento para carne. Rústico para um taurino, longevo e dócil. Exigência nutricional intermediária — aproveita bem volumoso e pasto de qualidade, mas responde a concentrado.', '{"semiconfinamento","pasto","confinamento"}'::text[], '{"gado_leite","recria","cria","manutencao","semi_confinamento"}'::text[], 'gado_leite', null, null, 'Porte grande, com aproveitamento também para carne no descarte. Confirmar peso e consumo com o produtor.', 'Produção e teor de sólidos variam com manejo, volumoso e ambiente — o guia não fixa faixa para esta raça. Use o controle leiteiro do cliente. Dimensionamento da fábrica: nº de vacas em lactação x kg de concentrado/vaca/dia da formulação, mais o consumo dos lotes de recria e vacas secas.', null, '{}'::text[], '{"Concentrado no cocho da ordenha","Concentrado sobre volumoso de qualidade"}'::text[], '{"farelada"}'::text[], '{"milho","sorgo","farelo-soja","farelo-trigo","polpa-citrica","casquinha-soja","calcario-calcitico","fosfato-bicalcico","sal-comum","sal-mineral","nucleo-premix"}'::text[], '{"A Branorte fornece equipamentos para produção de ração FARELADA; peletização exige processo adicional não incluído.","Volumoso não entra na fábrica.","Dieta completa (TMR) é vagão misturador."}'::text[], '{"Quantas vacas em lactação e quantas em recria/secas?","Usa a raça só para leite ou também aproveita a carne no descarte?","O concentrado é comprado pronto, ou já mistura na fazenda?","Trabalha com fórmulas diferentes por lote?","Tem milho ou sorgo próprio para moer?"}'::text[], '{}'::text[], 'Moagem, dosagem e mistura do concentrado farelado, incluindo linhas separadas para lactação, recria e secas se o produtor trabalhar com lotes. Volumoso fora; TMR é vagão misturador.', '{"MOINHO","MISTURADOR","TRANSPORTADOR","ELEVADOR","MOEGA","CAIXA","BALANCA","ENSACADEIRA","SILO"}'::text[], 'Perfil de rebanho estável, com produtor que pensa em longevidade da vaca. A dieta trabalha volumoso de qualidade mais concentrado ajustado; a fábrica Branorte cobre a parte do concentrado, com o grão da própria fazenda.', '{"Não prometer litros, sólidos ou longevidade como resultado do equipamento.","Não citar índices de produção sem o controle leiteiro do cliente.","Não oferecer ração peletizada.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'É vaca que fica no rebanho muitos anos, então o que o senhor quer é constância, não pico. A fábrica moe o seu grão e mistura o concentrado da lactação, da recria e da vaca seca — cada um com a fórmula certa. O capim e a silagem seguem por fora, como sempre.', 'Pardo-Suíço é vaca longeva, de dupla aptidão, com exigência de concentrado intermediária — nem free-stall de Holandês, nem só pasto. A fábrica Branorte faz o concentrado dentro da fazenda. Volumoso e dieta completa ficam fora.', 'Sul, Sudeste e regiões serranas.', 'pardo-suico', '🐄', 'aprovado', true, '{"Não há faixa de produção validada para esta raça no material de origem — levantar com o cliente ou com a associação antes de citar número."}'::text[], '{"embrapa-gado-leite","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1150),
  ('mesticas-holandes-zebu', 'Mestiças Holandês x Zebu (graus de sangue)', '{"mestiça","meio-sangue","F1 Holandês x Zebu","3/4","vaca de leite comum"}'::text[], 'bovinos', 'leite', 'cruzamento', 'Cruzamento Holandês x zebuíno, sem registro', 'Leite comercial a pasto e semiconfinamento', 'Vacas de cruzamento Holandês x zebuíno criadas sem registro, com grau de sangue variável de propriedade para propriedade. Combinam produção com rusticidade e menor custo de manutenção; são a base do leite a pasto. Não confundir com o Girolando: aquele é o recorte REGISTRADO, com padrão e graus de sangue definidos pela associação; as mestiças são cruzamentos sem registro e grau incerto. Os dois recortes se confundem no campo — muita vaca chamada de girolando não tem registro — e por isso não se somam. Juntos formam a maior parte do leite produzido no Brasil; separadamente, não há número validado para nenhum dos dois.', '{"pasto","semiconfinamento"}'::text[], '{"gado_leite","cria","recria","manutencao","proteica","semi_confinamento"}'::text[], 'gado_leite', null, null, 'Porte variável conforme o grau de sangue. Não estimar — perguntar ao produtor.', 'Produção varia muito com o grau de sangue: em campo aparecem rebanhos de cerca de 8 L/vaca/dia até acima de 25 L/vaca/dia. É faixa de referência, não meta — depende de grau de sangue, pasto, manejo e ambiente. Use o tanque e o controle do cliente. Dimensionamento: nº de vacas em lactação x kg de concentrado/vaca/dia da formulação.', null, '{}'::text[], '{"Concentrado no cocho da ordenha","Suplemento mineral e proteico a pasto","Concentrado ajustado por faixa de produção"}'::text[], '{"farelada"}'::text[], '{"milho","sorgo","raspa-mandioca","farelo-soja","farelo-algodao","caroco-algodao","farelo-trigo","farelo-arroz","concentrado-proteico","calcario-calcitico","sal-comum","sal-mineral","fosfato-bicalcico","nucleo-premix","ureia"}'::text[], '{"A Branorte fornece equipamentos para produção de ração FARELADA; peletização exige processo adicional não incluído.","Pasto, cana e silagem ficam fora da fábrica.","Dieta completa (TMR) é vagão misturador."}'::text[], '{"Qual o grau de sangue predominante e quantas vacas estão em lactação?","Hoje é uma ração só pra todas as vacas ou já tem separação por produção?","Compra ração pronta em saco ou concentrado/núcleo pra misturar?","Tem milho próprio para moer, e quanto sobra por safra?","Quanto o senhor gasta por mês em ração comprada hoje?"}'::text[], '{}'::text[], 'Moagem de milho, sorgo ou raspa e mistura com farelos, núcleo e minerais. Permite mais de uma fórmula: concentrado das vacas de maior produção, concentrado leve das de menor e suplemento mineral proteico para o pasto. Volumoso fica fora; TMR é vagão misturador.', '{"MOINHO","MISTURADOR","TRANSPORTADOR","MOEGA","CAIXA","BALANCA","ENSACADEIRA","SUPORTE_BAG"}'::text[], 'Público grande e pulverizado, de pequeno e médio produtor, que já compra saco de ração e já tem milho. A fábrica Branorte permite fazer o concentrado na propriedade e ajustar a fórmula ao grau de sangue e à produção de cada lote.', '{"Não prometer litros/dia como resultado do equipamento.","Não citar percentual do leite nacional produzido por mestiças.","Não somar a participação das mestiças com a do Girolando — os recortes se sobrepõem.","Não oferecer ração peletizada.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'O senhor tem vaca de grau de sangue diferente no mesmo lote, e hoje provavelmente dá a mesma ração pra todas. A fábrica aqui deixa o senhor fazer mais de uma fórmula: uma mais reforçada pras que produzem mais e uma mais leve pras outras — com o seu milho, moído aí mesmo. O capim continua sendo capim, não entra na fábrica.', 'Vaca mestiça de Holandês com zebu, sem registro, grau de sangue variando de fazenda pra fazenda — junto com o Girolando, é o que sustenta a maior parte do leite do país. Cada grau de sangue pede um concentrado diferente. A fábrica Branorte moe o milho do produtor e mistura o concentrado certo pra cada lote. Pasto e silagem ficam de fora.', 'Todo o Brasil, com peso em pequenos e médios produtores.', 'mestica-pasto', '🐄', 'aprovado', true, '{"Faixa de produção por grau de sangue é referência de campo — validar com o controle do cliente.","Participação das mestiças e do Girolando no leite nacional: sem número validado; tratar de forma qualitativa."}'::text[], '{"embrapa-gado-leite","girolando","branorte-catalogo","branorte-engenharia"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1160),
  ('cobb-500', 'Cobb 500', '{"Cobb","Cobb500","Cobb-Vantress"}'::text[], 'aves', 'frango_corte', 'linhagem', 'Linhagem comercial de corte de crescimento rápido (Cobb-Vantress / Agroceres)', 'Corte industrial, abate para carne branca (peito, cortes e integração)', 'Linhagem de frango de corte de crescimento rápido, com alta taxa de ganho e bom rendimento de peito. Junto com a Ross, responde pela maior parte do frango industrial abatido no país. Depende de ambiente controlado (climatização, densidade, ventilação) e de programa nutricional dividido por fase.', '{"integracao","comercial","independente"}'::text[], '{"frango_inicial","frango_crescimento","frango_final"}'::text[], 'frango_crescimento', null, null, 'Faixa de referencia de mercado: peso vivo de cerca de 2,8 a 3,2 kg em torno de 42 a 45 dias. Nao e meta: peso e idade de abate variam com sexo, ambiente, sanidade e programa nutricional, e a curva oficial esta na tabela do manual Cobb, edicao vigente.', 'Consumo e conversão por fase devem ser lidos na tabela do manual Cobb, edição vigente, separados por sexo e idade. Não use número de memória: muda por edição do manual, sexo, idade de abate, ambiente e status sanitário.', null, '{}'::text[], '{"ração completa farelada por fase","concentrado/núcleo misturado com milho da propriedade"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","oleo-gordura","nucleo-premix","calcario-calcitico","fosfato-bicalcico","sal-comum","lisina","metionina","fitase-enzimas","adsorvente-micotoxinas","farelo-trigo","sorgo","ddg-ddgs"}'::text[], '{"A Branorte fornece equipamentos para producao de racao FARELADA; peletizacao exige processo adicional nao incluido.","Micro ingredientes (aminoacidos, enzimas, premix) exigem pesagem precisa e tempo de mistura respeitado — dimensionar balanca e misturador para isso.","Dosagem de ingrediente liquido ou umido (oleo, gordura) nao e escopo padrao da fabrica: se a formula previr, alinhar antes da proposta."}'::text[], '{"Qual manual da linhagem o senhor segue hoje, e de que ano é a edição?","O senhor cria macho, fêmea ou lote misto, e com que idade abate?","Quantas fases de ração o programa tem e qual a formulação de cada uma?","Quem formula: a integradora, um zootecnista contratado ou o senhor mesmo?","O senhor compra ração pronta, concentrado ou pretende comprar ingrediente e fabricar?"}'::text[], '{}'::text[], 'Recepcao e pre-limpeza do grao, moagem fina e uniforme, dosagem/pesagem de macro e micro ingredientes, mistura homogenea, transporte e ensaque ou descarga a granel. Produto final: racao FARELADA. Dosagem de ingrediente liquido ou umido nao faz parte do escopo padrao — se a formula previr oleo ou gordura, alinhar antes da proposta.', '{"MOEGA","PRE_LIMPEZA","ELEVADOR","MOINHO","SILO","CAIXA","BALANCA","CACAMBA_PESAGEM","MISTURADOR","TRANSPORTADOR","ENSACADEIRA","SUPORTE_BAG"}'::text[], 'O produtor de Cobb 500 formula por fase e cobra regularidade do lote. O que a fábrica entrega é constância: granulometria estável na moagem e mistura homogênea, para que o premix e os aminoácidos cheguem iguais em todo o lote. Fórmula bem calculada só se expressa se a mistura for uniforme.', '{"Não prometer conversão alimentar, ganho de peso ou peso de abate como resultado do equipamento.","Não afirmar que a linhagem é ''a mais eficiente do mercado'' nem citar percentual de participação no abate nacional.","Não citar número de conversão do manual de memória.","Não dizer que a Branorte peletiza ou extruda.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'Diga assim: ''a genética já está no pinto; o que o senhor controla é a ração e o galpão''. A linhagem é de ciclo curto, então erro de fórmula ou mistura mal feita aparece rápido no lote. A fábrica própria serve para ter milho moído no ponto certo e mistura igual todo dia, e para o senhor comprar ingrediente na hora que o preço permite. Índice de conversão quem define é o manual da linhagem e o manejo — o equipamento entrega regularidade de processo.', 'Frango industrial de ciclo curto, quatro fases de ração, galpão climatizado. A fábrica precisa de moagem fina constante, mistura homogênea e pesagem confiável de micro ingredientes. Índice de desempenho está no manual da linhagem — não prometa conversão.', 'Sul (SC, PR, RS) e São Paulo, polo integrador exportador; presente em todo o Brasil.', null, '🐔', 'aprovado', true, '{"Todo número de desempenho (conversão, ganho, consumo, peso) depende do manual oficial da linhagem: registrar edição, ano, sexo e idade antes de citar.","Participação de mercado da linhagem no abate nacional: sem fonte auditada — manter como ''maior parte do frango industrial'', sem percentual.","Linhagens comerciais de aves não são distinguíveis visualmente entre si; não usar aparência para identificar linhagem no galpão."}'::text[], '{"manual-cobb","embrapa-suinos-aves","rostagno-tabelas","mapa-alimentacao-animal","branorte-catalogo","branorte-engenharia"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1170),
  ('ross-308', 'Ross 308 / Ross AP', '{"Ross","Ross 308","Ross AP","Aviagen Ross"}'::text[], 'aves', 'frango_corte', 'linhagem', 'Linhagem comercial de corte de crescimento rápido (Aviagen / Agroceres Ross)', 'Corte industrial, abate para carne branca e integração', 'Linhagem de frango de corte de crescimento rápido, com boa uniformidade de lote e rendimento de peito. Junto com a Cobb, ocupa a maior parte do abate industrial brasileiro. Como toda linhagem de ciclo curto, depende de ambiente controlado e de programa nutricional por fase.', '{"integracao","comercial","independente"}'::text[], '{"frango_inicial","frango_crescimento","frango_final"}'::text[], 'frango_crescimento', null, null, 'Faixa de referencia de mercado: peso vivo de cerca de 2,9 a 3,3 kg em torno de 42 a 45 dias. Nao e meta nem compromisso contratual: varia com sexo, ambiente, sanidade e programa nutricional; a curva oficial esta no manual Ross, edicao vigente.', 'Consumo e conversão por fase devem ser consultados no manual Ross, edição vigente, por sexo e idade. Não citar número de memória: varia por edição, sexo, idade de abate, ambiente e sanidade.', null, '{}'::text[], '{"ração completa farelada por fase","concentrado/núcleo misturado com milho da propriedade"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","oleo-gordura","nucleo-premix","calcario-calcitico","fosfato-bicalcico","sal-comum","lisina","metionina","fitase-enzimas","adsorvente-micotoxinas","farelo-trigo","sorgo","ddg-ddgs"}'::text[], '{"A Branorte fornece equipamentos para producao de racao FARELADA; peletizacao exige processo adicional nao incluido.","Se o programa nutricional do cliente exigir peletizado, a Branorte nao atende esse escopo. Dizer isso na primeira conversa, sem sugerir complemento por terceiros.","Pequenas variacoes de formula alteram resultado: exigir pesagem precisa de micro ingredientes e tempo de mistura respeitado.","Dosagem de ingrediente liquido ou umido nao e escopo padrao — alinhar antes da proposta."}'::text[], '{"O programa da integradora exige ração peletizada em alguma fase? Em qual?","Qual edição do manual Ross o senhor usa como referência de fase?","Cria macho, fêmea ou misto, e com qual idade de abate?","Quem formula a ração e com que frequência a fórmula muda?","Qual o volume mensal de ração e quantas fases diferentes precisam ser produzidas?"}'::text[], '{}'::text[], 'Pre-limpeza, moagem fina e regular, dosagem e pesagem de macro e micro ingredientes, mistura homogenea, transporte e ensaque ou granel. Produto final: racao FARELADA. Dosagem de ingrediente liquido ou umido nao faz parte do escopo padrao — se a formula previr oleo ou gordura, alinhar antes da proposta.', '{"MOEGA","PRE_LIMPEZA","ELEVADOR","MOINHO","SILO","CAIXA","BALANCA","CACAMBA_PESAGEM","MISTURADOR","TRANSPORTADOR","ENSACADEIRA","SUPORTE_BAG"}'::text[], 'Cliente de Ross acompanha resultado lote a lote e sente variação de fórmula rápido. O ponto de venda da fábrica é constância de processo: mesma granulometria, mesmo tempo de mistura, mesma pesagem todo dia. Sem isso, a fórmula do zootecnista chega diferente em cada carga.', '{"Nao dizer que a linhagem ''exige racao peletizada de qualidade'' nem qualquer variacao disso.","Nao afirmar que a Branorte peletiza, extruda ou ''faz peletizado depois''.","Nao citar numero de conversao de manual — nem como promessa, nem como referencia de venda. Conversao se le no manual da linhagem, edicao vigente, por sexo e idade.","Nao citar percentual de participacao da linhagem no frango de corte nacional.","Nao prometer indice zootecnico como resultado do equipamento.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'A linhagem pode ser alimentada com diferentes formas físicas conforme o programa nutricional e o manejo. A Branorte fornece equipamentos para produção de ração FARELADA; peletização exige processo adicional não incluído. Deixe isso claro na primeira conversa: se a integradora exige ração peletizada, o escopo da fábrica muda e o senhor precisa alinhar antes de fechar. Para quem trabalha farelado, o ganho está em moer no ponto, misturar igual e ter o ingrediente na hora certa.', 'Frango industrial de ciclo curto, mesma lógica de quatro fases da Cobb. Muito sensível a variação de fórmula, então a fábrica tem que repetir o processo igual. Ração FARELADA — se o programa do cliente pede peletizado, é processo adicional que a Branorte não fornece.', 'Forte no Sul e em São Paulo; presente em todo o cinturão integrador do país.', null, '🐔', 'aprovado', true, '{"Números de conversão e consumo dependem do manual oficial: registrar edição, ano, sexo e idade antes de qualquer citação.","Participação da linhagem no abate nacional: sem fonte auditada; manter qualitativo.","Confirmar com o cliente, caso a caso, se o programa exige forma física peletizada — isso define se a Branorte atende o escopo.","Linhagens comerciais de aves não são distinguíveis visualmente; não usar aparência para identificação."}'::text[], '{"manual-ross","embrapa-suinos-aves","rostagno-tabelas","mapa-alimentacao-animal","branorte-catalogo","branorte-engenharia"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1180),
  ('embrapa-021', 'Embrapa 021 (frango de corte de crescimento lento)', '{"Embrapa 021","frango Embrapa","corte de crescimento lento"}'::text[], 'aves', 'frango_corte', 'linhagem', 'Linhagem nacional Embrapa para corte alternativo / caipira industrial', 'Corte alternativo, carne firme para nicho caipira/colonial', 'Linhagem nacional desenvolvida pela Embrapa para sistemas alternativos de corte, com crescimento lento e abate mais tardio que as linhagens industriais. Maior rusticidade e menor exigência de ambiente controlado, voltada a carne de nicho caipira/colonial.', '{"familiar","comercial","pasto"}'::text[], '{"frango_inicial","frango_crescimento","frango_final","caipira"}'::text[], 'caipira', null, null, 'Faixa de referência citada no material antigo: abate entre 70 e 90 dias. Idade e peso variam com o sistema, a alimentação e o mercado atendido.', 'Consumo total do ciclo é maior que o das linhagens industriais pelo tempo de criação, mas por dia a exigência é menor. Faixas por fase devem sair da recomendação Embrapa para a linhagem e da tabela de exigências adotada pelo formulador.', null, '{}'::text[], '{"ração farelada de menor densidade nutricional","núcleo/concentrado misturado com milho e ingredientes da propriedade","ração complementada com pastejo"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","nucleo-premix","calcario-calcitico","sal-comum","fosfato-bicalcico","farelo-trigo","farelo-arroz","quirera-arroz","sorgo","milheto","oleo-gordura","adsorvente-micotoxinas"}'::text[], '{"A Branorte fornece equipamentos para produção de ração FARELADA; peletização exige processo adicional não incluído.","Ciclo longo aumenta o volume total de ração — dimensionar a fábrica pelo consumo anual, não pelo lote.","Uso de ingrediente da propriedade exige atenção a umidade e armazenagem antes da moagem."}'::text[], '{"Com quantos dias o senhor abate e para qual mercado vende?","As aves têm acesso a piquete ou é confinado em galpão?","O senhor já tem milho próprio ou compra tudo?","Trabalha com núcleo, concentrado ou ração pronta hoje?","Quantas aves por lote e quantos lotes por ano?"}'::text[], '{}'::text[], 'Moagem de milho e mistura com núcleo/concentrado e demais ingredientes; ração FARELADA. Escala menor, com foco em custo de investimento e simplicidade de operação.', '{"MOEGA","ELEVADOR","MOINHO","MISTURADOR","CAIXA","BALANCA","TRANSPORTADOR","ENSACADEIRA","SUPORTE_BAG"}'::text[], 'É o cliente que foge do modelo industrial e formula com o que tem na propriedade. Ciclo longo significa mais ração no total do lote, mesmo com fórmula menos densa — volume de fábrica existe. Encaixe natural para fábrica pequena e média que atende mercado regional.', '{"Não prometer idade de abate, peso ou conversão como resultado do equipamento.","Não vender como ''frango caipira certificado'' — certificação depende de norma e sistema de criação, não da fábrica.","Não dizer que a Branorte peletiza ou extruda.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'Fale direto: ''o frango demora mais, entao o senhor gasta mais racao no total, mesmo que a formula seja mais barata''. E um perfil que costuma ja ter milho na propriedade e quer comprar so o nucleo — o ganho e moer e misturar em casa em vez de comprar racao pronta. Retorno do investimento depende do volume, do preco do ingrediente e do preco da racao comprada: monte a conta com os numeros da fazenda, sem prometer prazo.', 'Frango de crescimento lento, ciclo longo, fórmula menos densa e uso de ingrediente da propriedade. Consome mais ração no total do ciclo. Fábrica pequena/média com moinho e misturador atende bem, produzindo farelado.', 'Produção familiar e agroindústria de nicho em várias regiões do país.', null, '🐓', 'aprovado', true, '{"Confirmar com a Embrapa Suínos e Aves a disponibilidade e a recomendação nutricional vigente da linhagem 021.","Idade e peso de abate: registrar fonte e edição antes de citar como faixa.","Não há foto aprovada para esta linhagem; imagem permanece nula."}'::text[], '{"embrapa-suinos-aves","rostagno-tabelas","mapa-alimentacao-animal","branorte-catalogo","branorte-engenharia"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1190),
  ('isa-brown', 'Isa Brown', '{"ISA Brown","Isa","poedeira vermelha ISA"}'::text[], 'aves', 'postura', 'linhagem', 'Híbrida semipesada de postura, ovo de casca marrom (linha ISA / Hendrix)', 'Produção de ovos de mesa, casca marrom', 'Hibrida comercial de postura de casca marrom, obtida do cruzamento Rhode Island Red x Rhode Island White. Rustica e de manejo simples, com boa persistencia de postura. E uma das linhagens usadas nas granjas brasileiras de ovo vermelho.', '{"comercial"}'::text[], '{"poedeira_inicial","poedeira_crescimento","pre_postura","postura"}'::text[], 'postura', null, null, 'Ave semipesada, faixa de referência de 1,9 a 2,1 kg. Produção de referência citada: cerca de 300 a 320 ovos por ciclo/ano — número depende da idade final considerada, do manejo e do ambiente, e o valor oficial está no manual da linhagem.', 'Faixa de referência de consumo citada no material antigo: cerca de 110 a 120 g por ave por dia na postura. É referência — varia com peso corporal da ave, temperatura do galpão, densidade energética da ração e fase do ciclo. O valor oficial está na tabela de manejo da linhagem, edição vigente.', null, '{}'::text[], '{"ração farelada por fase (cria, recria, pré-postura, postura 1 e 2)","núcleo/concentrado misturado com milho próprio"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","calcario-calcitico","fosfato-bicalcico","sal-comum","nucleo-premix","oleo-gordura","metionina","lisina","fitase-enzimas","adsorvente-micotoxinas","farelo-trigo","farelo-arroz"}'::text[], '{"A Branorte fornece equipamentos para produção de ração FARELADA; peletização exige processo adicional não incluído.","Fórmula de postura tem alta inclusão de calcário — atenção à abrasividade e ao tempo de mistura.","Granja com lotes escalonados produz mais de uma fórmula por dia: dimensionar a fábrica por número de fórmulas, não só por tonelagem."}'::text[], '{"Quantas aves alojadas hoje e qual a idade média do lote?","O senhor trabalha com quantas fases de ração da recria até a postura?","Já enfrenta problema de casca fina ou de ovo trincado no lote?","Compra ração pronta, concentrado ou pretende comprar ingrediente a granel?","Tem lote único ou lotes escalonados por idade? (isso define quantas fórmulas por dia a fábrica precisa produzir)"}'::text[], '{}'::text[], 'Moagem de milho, dosagem de calcário e demais macro ingredientes, pesagem de micro (premix, aminoácidos), mistura homogênea e ensaque ou granel. Produto: ração FARELADA de postura e de recria.', '{"MOEGA","PRE_LIMPEZA","ELEVADOR","MOINHO","SILO","CAIXA","BALANCA","CACAMBA_PESAGEM","MISTURADOR","TRANSPORTADOR","ENSACADEIRA","SUPORTE_BAG"}'::text[], 'Postura e ciclo longo: a mesma ave fica na granja por muitos meses e come todo dia. Isso significa demanda de racao constante e previsivel. A fabrica entrega controle de custo por tonelada e regularidade de processo — moagem estavel, pesagem confiavel e mistura homogenea, para que a formula do formulador chegue igual em todo o lote.', '{"Não prometer número de ovos por ave, qualidade de casca ou persistência de postura como resultado do equipamento.","Não citar percentual de cálcio da fórmula como recomendação da Branorte — quem define é o formulador.","Não dizer que a Branorte peletiza ou extruda.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'Explique o ciclo: ''da pintainha ate o fim da postura, essa ave come da sua racao todo dia''. Por isso, quem tem fabrica trava o custo do maior item da granja. Reforce o lado operacional: formula de postura carrega bastante calcario, e mistura homogenea e o que garante que cada ave receba a formula que o formulador desenhou. Quantidade e qualidade de ovo dependem da linhagem, do manejo e da formulacao — o equipamento entrega regularidade de processo, nao indice.', 'Poedeira de ovo vermelho, ciclo longo, ração da cria à postura. Fórmula de postura tem muito calcário: exige mistura homogênea e pesagem confiável. Ovo por ave está no manual da linhagem — não prometa produção.', 'São Paulo (região de Bastos), Minas Gerais, Paraná e Espírito Santo; grandes granjas comerciais.', 'isa-brown', '🥚', 'aprovado', true, '{"Ovos por ciclo e consumo diário: confirmar no manual oficial da linhagem, com edição, ano e idade final considerada.","Percentuais de cálcio da fórmula de postura foram retirados por falta de fonte — reinserir apenas com referência (tabela de exigências adotada).","Linhagens comerciais de postura não são distinguíveis visualmente entre si; a foto ilustra tipo de ave, não identifica linhagem."}'::text[], '{"manual-isa","embrapa-suinos-aves","rostagno-tabelas","mapa-alimentacao-animal","branorte-catalogo","branorte-engenharia"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1200),
  ('hy-line', 'Hy-Line Brown / Hy-Line W-36', '{"Hy-Line","Hyline Brown","W-36","Hy-Line W-36"}'::text[], 'aves', 'postura', 'linhagem', 'Híbridas comerciais de postura: Brown (semipesada, ovo marrom) e W-36 (leve, ovo branco)', 'Produção de ovos de mesa — casca marrom (Brown) e casca branca (W-36)', 'Duas linhas comerciais do mesmo programa genético: a Brown, semipesada, para ovo de casca marrom; e a W-36, leve, para ovo branco. A W-36 tem peso corporal menor e consumo diário mais baixo que a Brown, o que muda o cálculo de ração por ave alojada.', '{"comercial"}'::text[], '{"poedeira_inicial","poedeira_crescimento","pre_postura","postura"}'::text[], 'postura', null, null, 'Faixas de referência: W-36 leve, em torno de 1,5 kg; Brown semipesada, em torno de 2 kg. Produção citada como referência: cerca de 300 a 320 ovos por ciclo/ano — depende da idade final considerada, do manejo e do ambiente; número oficial está no manual.', 'Faixa de referência citada no material antigo: cerca de 100 a 115 g por ave por dia, sendo a linha leve na parte baixa da faixa e a semipesada acima. É referência — varia com peso da ave, temperatura, densidade energética da ração e fase. O valor oficial está no manual de manejo da linhagem, edição vigente.', null, '{}'::text[], '{"ração farelada de postura por fase","ração de recria e pré-postura","núcleo/concentrado misturado com milho próprio"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","calcario-calcitico","fosfato-bicalcico","sal-comum","nucleo-premix","oleo-gordura","metionina","lisina","fitase-enzimas","adsorvente-micotoxinas","farelo-trigo","sorgo"}'::text[], '{"A Branorte fornece equipamentos para produção de ração FARELADA; peletização exige processo adicional não incluído.","Duas linhas na mesma granja significam fórmulas distintas: dimensionar a fábrica por número de fórmulas e trocas, não apenas por tonelagem total.","Alta inclusão de calcário na fase de postura — considerar abrasividade e homogeneidade de mistura."}'::text[], '{"A granja trabalha com ovo branco, marrom ou os dois?","Se tem as duas linhas, elas ficam em galpões separados? Quantas fórmulas diferentes o senhor precisa produzir por dia?","Qual o número de aves alojadas por linha e a idade dos lotes?","Quem faz a formulação e com que frequência ela é revisada?","O senhor compra ração pronta hoje ou já trabalha com núcleo e milho próprio?"}'::text[], '{}'::text[], 'Moagem, dosagem de calcário e macro ingredientes, pesagem de micro, mistura homogênea, ensaque ou granel. Produto: ração FARELADA. Granja com duas linhas produz duas famílias de fórmula.', '{"MOEGA","PRE_LIMPEZA","ELEVADOR","MOINHO","SILO","CAIXA","BALANCA","CACAMBA_PESAGEM","MISTURADOR","TRANSPORTADOR","ENSACADEIRA","SUPORTE_BAG"}'::text[], 'O que separa as duas linhas, do ponto de vista da fábrica, é a curva de consumo: ave leve come menos por dia e exige fórmula mais concentrada para receber a mesma quantidade de nutriente. Quem fabrica em casa consegue ajustar essa densidade sem depender do que o fornecedor tem em estoque.', '{"Nao usar superlativo comparativo entre linhagens (tipo ''mais eficiente'' ou ''melhor conversao do mercado''): comparacao so com dado dos manuais das duas linhas, mesma edicao e mesma idade.","Nao prometer racao por duzia, numero de ovos ou conversao como resultado do equipamento.","Nao citar numero de consumo ou producao do manual sem indicar edicao, ano e idade.","Nao dizer que a Branorte peletiza ou extruda.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'Use a diferença prática: ''a branca é uma ave menor, come menos por dia — então a ração dela precisa ser mais concentrada para entregar o mesmo nutriente''. Se a granja tem as duas linhas, são duas fórmulas diferentes convivendo, e isso pesa no dimensionamento da fábrica. Não venda promessa de eficiência: a curva de consumo e produção é a do manual da linhagem.', 'Brown para ovo marrom, W-36 leve para ovo branco. A leve come menos por dia, então a fórmula precisa ser mais concentrada. Fábrica própria permite ajustar densidade por linha e por fase. Índice de produção fica no manual.', 'Região de Bastos-SP e demais cinturões de postura; a linha branca é mais presente onde há demanda por ovo branco.', null, '🥚', 'aprovado', true, '{"Comparação de eficiência entre W-36 e Brown: só pode ser feita com dados dos manuais das duas linhas, na mesma edição e mesma idade. Sem isso, manter descrição qualitativa.","Consumo diário e produção anual: confirmar no manual oficial (edição, ano, linha, idade).","Não há foto aprovada; linhagens comerciais de postura não são distinguíveis visualmente entre si."}'::text[], '{"manual-hyline","embrapa-suinos-aves","rostagno-tabelas","mapa-alimentacao-animal","branorte-catalogo","branorte-engenharia"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1210),
  ('lohmann', 'Lohmann Brown / Lohmann LSL', '{"Lohmann","Lohmann Brown","LSL","Lohmann LSL Lite"}'::text[], 'aves', 'postura', 'linhagem', 'Híbridas comerciais de postura: Brown (ovo marrom) e LSL Lite (leve, ovo branco) — genética Lohmann / EW Group', 'Produção de ovos de mesa — casca marrom-clara (Brown) e branca (LSL)', 'Programa genético com duas linhas comerciais: a Brown, semipesada, de ovo marrom-claro; e a LSL, leve, especializada em ovo branco. Boa persistência de postura ao longo do ciclo e resposta consistente a fórmula equilibrada.', '{"comercial"}'::text[], '{"poedeira_inicial","poedeira_crescimento","pre_postura","postura"}'::text[], 'postura', null, null, 'Produção citada como referência: cerca de 300 a 320 ovos por ciclo/ano. Depende da idade final considerada, do manejo e do ambiente; o número oficial está no manual da linhagem.', 'Consumo diário por ave deve ser lido no guia de manejo da linhagem, edição vigente, por linha (Brown ou LSL), idade e peso corporal. A ave leve consome menos por dia que a semipesada — o valor exato varia com temperatura, densidade da ração e fase.', null, '{}'::text[], '{"ração farelada de postura fase 1 e fase 2","ração de recria e pré-postura","núcleo/concentrado misturado com milho próprio"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","calcario-calcitico","fosfato-bicalcico","sal-comum","nucleo-premix","oleo-gordura","metionina","lisina","fitase-enzimas","adsorvente-micotoxinas","farelo-trigo","farelo-girassol"}'::text[], '{"A Branorte fornece equipamentos para produção de ração FARELADA; peletização exige processo adicional não incluído.","Fase 1 e fase 2 de postura são fórmulas diferentes — prever trocas de fórmula no dimensionamento.","Alta inclusão de calcário exige atenção a abrasividade, dosagem e tempo de mistura."}'::text[], '{"O senhor trabalha com a linha marrom, a branca ou as duas?","Já separa fórmula de fase 1 e fase 2 de postura, ou usa uma só o ciclo inteiro?","Com que idade os lotes estão hoje e quando entra o próximo?","Quantas toneladas de ração por mês a granja consome?","Compra ração pronta, concentrado ou ingrediente a granel?"}'::text[], '{}'::text[], 'Moagem, dosagem de calcário e macro, pesagem de micro, mistura homogênea, ensaque ou granel. Produto: ração FARELADA, com fórmulas distintas para fase 1 e fase 2 de postura.', '{"MOEGA","PRE_LIMPEZA","ELEVADOR","MOINHO","SILO","CAIXA","BALANCA","CACAMBA_PESAGEM","MISTURADOR","TRANSPORTADOR","ENSACADEIRA","SUPORTE_BAG"}'::text[], 'Persistencia de postura e ciclo longo com formula estavel. Onde a fabrica entra e na regularidade de processo: mesma moagem, mesma mistura, mesma pesagem, dia apos dia. Quem produz em casa tambem controla o momento da troca de formula, em vez de depender do prazo do fornecedor.', '{"Não prometer persistência de postura, qualidade de casca ou número de ovos como resultado do equipamento.","Não comparar eficiência com outras linhagens sem dado de manual das duas, mesma edição e idade.","Não dizer que a Branorte peletiza ou extruda.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'Diga que depois do pico a formula muda — o programa reduz proteina e ajusta calcio — e que quem tem fabrica faz essa troca no dia certo, sem esperar pedido de fornecedor. Reforce a regularidade: a formula desenhada pelo formulador so chega igual a ave se a moagem e a mistura forem constantes. Producao por ave e assunto do manual da linhagem e do manejo.', 'Duas linhas: marrom e branca. Ciclo longo com fase 1 e fase 2 de postura, ajustando proteína e cálcio depois do pico. Fábrica própria dá controle de custo e constância de fórmula. Números de produção ficam no manual.', 'Grandes granjas comerciais de São Paulo, Minas Gerais e Região Sul.', 'lohmann-brown', '🥚', 'aprovado', true, '{"Produção anual e consumo diário: confirmar no guia de manejo oficial, com edição, ano, linha e idade final.","Recomendações de proteína e cálcio por fase pertencem ao formulador — não registrar valores no card sem fonte.","Foto ilustra tipo de ave; linhagens comerciais de postura não são distinguíveis visualmente entre si."}'::text[], '{"manual-lohmann","embrapa-suinos-aves","rostagno-tabelas","mapa-alimentacao-animal","branorte-catalogo","branorte-engenharia"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1220),
  ('white-leghorn', 'White Leghorn (Leghorn branca)', '{"Leghorn","Leghorn branca","White Leghorn","poedeira leve branca"}'::text[], 'aves', 'postura', 'raca', 'Raça leve clássica — base genética das poedeiras comerciais de ovo branco', 'Produção de ovos de mesa de casca branca; base genética das híbridas comerciais brancas', 'Raça leve de postura, precoce para entrar em produção e de baixo peso corporal. Serve de base genética para as linhagens comerciais de ovo branco. Como ave leve, tem consumo diário menor, o que exige ração com densidade de nutrientes maior para atender a exigência no volume que ela come.', '{"comercial"}'::text[], '{"poedeira_inicial","poedeira_crescimento","pre_postura","postura"}'::text[], 'postura', null, null, 'Faixa de referência de peso: 1,5 a 1,8 kg. Produção citada como referência: cerca de 300 a 320 ovos por ciclo/ano nas linhagens comerciais derivadas — depende da idade final considerada, do manejo e do ambiente; número oficial está no manual da linhagem.', 'Consumo diário por ave é menor que o das semipesadas, por ser ave de menor peso corporal. Faixas específicas devem sair do guia de manejo da linhagem comercial utilizada, edição vigente, por idade e peso — a raça em si não tem tabela comercial única.', null, '{}'::text[], '{"ração farelada de postura com densidade nutricional elevada","ração de recria e pré-postura","núcleo/concentrado misturado com milho próprio"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","calcario-calcitico","fosfato-bicalcico","sal-comum","nucleo-premix","oleo-gordura","metionina","lisina","fitase-enzimas","adsorvente-micotoxinas","farelo-trigo"}'::text[], '{"A Branorte fornece equipamentos para produção de ração FARELADA; peletização exige processo adicional não incluído.","Ração de alta densidade em ave de baixo consumo torna a homogeneidade de mistura mais crítica — não subdimensionar o misturador.","Alta inclusão de calcário: atenção a abrasividade, dosagem e tempo de mistura."}'::text[], '{"Qual linhagem comercial branca o senhor aloja hoje? (a base é Leghorn, mas o manual é da linhagem)","Quantas aves alojadas e qual a idade dos lotes?","O mercado que o senhor atende paga melhor pelo ovo branco ou pelo vermelho na sua região?","O senhor separa fórmula por fase da postura ou usa uma só?","Já mediu o consumo real por ave por dia no galpão, ou trabalha com estimativa?"}'::text[], '{}'::text[], 'Moagem fina e regular, dosagem de calcário e macro, pesagem precisa de micro, mistura homogênea, ensaque ou granel. Produto: ração FARELADA de alta densidade nutricional.', '{"MOEGA","PRE_LIMPEZA","ELEVADOR","MOINHO","SILO","CAIXA","BALANCA","CACAMBA_PESAGEM","MISTURADOR","TRANSPORTADOR","ENSACADEIRA","SUPORTE_BAG"}'::text[], 'Ave que come pouco por dia precisa de fórmula concentrada — não dá para ''diluir''. Isso torna a qualidade da mistura e a precisão da pesagem de micro ingredientes mais críticas, não menos. É exatamente o que uma fábrica própria bem dimensionada entrega.', '{"Não prometer número de ovos, consumo por dúzia ou qualidade de casca como resultado do equipamento.","Não afirmar que é a poedeira ''mais econômica'' ou usar qualquer superlativo de mercado.","Não dizer que a Branorte peletiza ou extruda.","Não usar aparência da ave para identificar linhagem comercial — a plumagem branca é característica da raça, não identifica o programa genético do lote.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'Explique o raciocínio: ''ela come menos, então cada grama de ração tem que valer mais''. Fórmula concentrada só funciona se a mistura for uniforme — se o micro ingrediente não se espalhar, parte do lote fica sem. E o calcário é crítico, porque o volume de ovos puxa muito cálcio da ave. Quantidade de ovos é assunto do manual da linhagem comercial e do manejo, não do equipamento.', 'Poedeira leve de ovo branco, come menos por dia, então a fórmula tem que ser mais concentrada. Cálcio para casca é ponto crítico pelo volume de ovos. Mistura homogênea e pesagem precisa valem mais aqui do que em ave pesada.', 'Base das granjas de ovo branco em todo o Brasil.', 'white-leghorn', '🥚', 'aprovado', true, '{"Consumo e produção devem vir do manual da linhagem comercial efetivamente alojada, não da raça — registrar edição, ano e idade.","Afirmações de eficiência alimentar comparativa foram retiradas por falta de fonte auditada.","A foto ilustra a raça; linhagens comerciais de postura não são distinguíveis visualmente entre si no galpão."}'::text[], '{"embrapa-suinos-aves","rostagno-tabelas","mapa-alimentacao-animal","manual-hyline","manual-lohmann","branorte-catalogo","branorte-engenharia"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1230),
  ('pescoco-pelado', 'Pescoço Pelado / Label Rouge', '{"Pescoço nu","Label Rouge","caipira francês"}'::text[], 'aves', 'caipira', 'linhagem', 'Linhagem caipira/colonial de corte (origem francesa, pescoço nu)', 'Carne de frango caipira/colonial para mercado de nicho.', 'Linhagem de corte de crescimento lento usada em criação a campo, caipira, colonial ou orgânica. Rústica, de plumagem variada e cara/pescoço sem penas. Pele fina, pouco acúmulo de gordura e carne firme, com mercado próprio em feira, açougue de bairro e restaurante.', '{"semiconfinamento","caipira","colonial","agroecologico"}'::text[], '{"frango_inicial","frango_crescimento","frango_final","caipira"}'::text[], 'caipira', null, null, 'Faixa de referência: em torno de 2,2 kg vivo por volta de 80-90 dias. Varia com linha, sexo, densidade, acesso a piquete e programa nutricional. O peso e a idade de abate oficiais estão no catálogo do fornecedor da genética, edição vigente.', 'Faixa de referência: consumo total por ave maior que o do frango industrial, porque o ciclo é bem mais longo, mesmo com consumo diário menor. O número da linha vem do catálogo do fornecedor; use o histórico do próprio produtor como base de cálculo.', null, '{}'::text[], '{"ração farelada completa produzida na propriedade","concentrado ou núcleo comprado + milho próprio","complemento de pastagem e verde no piquete"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","concentrado-proteico","nucleo-premix","calcario-calcitico","sal-comum","fosfato-bicalcico","farelo-trigo","farelo-arroz","sorgo","adsorvente-micotoxinas"}'::text[], '{"A linhagem pode ser alimentada com diferentes formas físicas conforme o programa nutricional e o manejo. A Branorte fornece equipamentos para produção de ração FARELADA; peletização exige processo adicional não incluído.","A formulação por fase é responsabilidade do técnico ou nutricionista do cliente. A Branorte fornece o equipamento, não a fórmula.","Certificação de caipira ou orgânico impõe regras de ingredientes e manejo — conferir o regulamento antes de prometer qualquer fórmula."}'::text[], '{"Quantas aves o senhor aloja por lote e quantos lotes faz por ano?","O milho é da propriedade ou comprado? Colhe e seca aqui?","Hoje compra ração pronta ou concentrado para misturar?","A criação é caipira certificada, orgânica ou colonial sem selo?","Quem formula a ração hoje — integradora, revenda ou técnico próprio?"}'::text[], '{}'::text[], 'Moagem do milho próprio em moinho de martelo e mistura com concentrado ou núcleo comprado. Volume pequeno, batida por batida, com pesagem em balança e ensaque em bag ou saco. Perfil clássico de Compacta JR / Compacta 01.', '{"MOINHO","MISTURADOR","BALANCA","ENSACADEIRA","SUPORTE_BAG","ACESSORIO"}'::text[], 'O produtor de caipira já compra ração pronta ou concentrado e tem milho na propriedade. Moer e misturar em casa dá controle sobre a fórmula por fase do ciclo longo e sobre o custo do saco. A Branorte entrega o conjunto de moagem e mistura dimensionado para esse volume.', '{"Prometer peso de abate, conversão alimentar ou uniformidade de lote como resultado do equipamento.","Dizer que a ração feita na fábrica antecipa o abate ou melhora a carne.","Afirmar que a máquina entrega ração peletizada ou extrusada.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'O senhor cria o frango por quase três meses, então a conta da ração não é o dia, é o ciclo inteiro. Se o milho é seu, faz sentido moer e misturar aqui dentro e comprar só o concentrado. A máquina não muda o frango — muda de quem o senhor compra o saco.', 'Frango caipira de ciclo longo, abatido por volta dos 80-90 dias conforme a linha e o manejo — a idade oficial está no catálogo da genética. Come menos por dia que o industrial, mas por muito mais tempo: o total de ração por lote é alto. Se o produtor tem milho, o encaixe é moinho + misturador para fazer a farelada em casa e comprar só o concentrado.', 'Produção familiar e agroecológica em todo o Brasil; presença forte em Minas Gerais, Nordeste e interior de São Paulo.', 'pescoco-pelado', '🐓', 'aprovado', true, '{"Confirmar peso e idade de abate no catálogo vigente do fornecedor da genética.","Levantar consumo médio por ave no ciclo com dados do próprio cliente antes de dimensionar."}'::text[], '{"embrapa-suinos-aves","rostagno-tabelas","mapa-alimentacao-animal","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1240),
  ('embrapa-051', 'Embrapa 051 (poedeira colonial)', '{"poedeira colonial Embrapa","galinha colonial 051","poedeira caipira nacional"}'::text[], 'aves', 'caipira', 'linhagem', 'Híbrida nacional de dupla aptidão (Rhode Island Red x Plymouth Rock Branca), desenvolvida pela Embrapa', 'Ovo caipira/colonial e carcaça no fim de ciclo, em criação familiar.', 'Híbrida nacional desenvolvida pela Embrapa para criação colonial com acesso a piquete. Dupla aptidão: põe ovo de casca creme a marrom e, ao fim do ciclo, ainda rende carcaça. Feita para aproveitar ingredientes da própria propriedade.', '{"colonial","caipira","agroecologico"}'::text[], '{"poedeira_inicial","poedeira_crescimento","pre_postura","postura","caipira"}'::text[], 'caipira', null, null, 'Faixa de referência: poedeira por volta de 2 kg; machos abatidos em torno de 120 dias com cerca de 2,5 kg. Depende de manejo, idade final considerada e alimentação. Os valores oficiais estão no material técnico da Embrapa.', 'Faixa de referência: consumo de ração por ovo maior que o de híbrida comercial de postura, por causa do sistema colonial e do ciclo. O custo por saco tende a ser menor porque a fórmula é menos densa. Confirmar com o histórico do produtor.', null, '{}'::text[], '{"ração farelada de postura produzida na propriedade","concentrado ou núcleo comprado + milho próprio","pastoreio e verde do piquete como complemento"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","concentrado-proteico","nucleo-premix","calcario-calcitico","fosfato-bicalcico","sal-comum","farelo-trigo","farelo-arroz","quirera-arroz","milheto","adsorvente-micotoxinas"}'::text[], '{"A linhagem pode ser alimentada com diferentes formas físicas conforme o programa nutricional e o manejo. A Branorte fornece equipamentos para produção de ração FARELADA; peletização exige processo adicional não incluído.","Ração de postura exige nível de cálcio próprio para casca — definição é do nutricionista, não do vendedor.","Ovo caipira com selo tem regra de ingrediente e de manejo; conferir antes de sugerir qualquer matéria-prima."}'::text[], '{"Quantas aves o senhor tem em postura hoje?","Também cria os machos para corte ou só trabalha com o ovo?","O milho é próprio? Tem secagem e armazenamento na propriedade?","Compra concentrado, núcleo ou ração pronta hoje?","Vende o ovo em feira, para mercado ou por entrega direta?"}'::text[], '{}'::text[], 'Moagem de milho e grãos da propriedade, mistura com concentrado ou núcleo e inclusão de calcário para casca. Volume pequeno, batida controlada por balança. Perfil de Compacta JR / Compacta 01.', '{"MOINHO","MISTURADOR","BALANCA","ENSACADEIRA","SUPORTE_BAG"}'::text[], 'É o produtor que já mistura milho próprio com concentrado, mas faz isso na pá e no olho. O misturador dá homogeneidade de batida e a balança dá controle do que entra. A venda é do conjunto de moagem e mistura, não da fórmula.', '{"Prometer número de ovos por ano, qualidade de casca ou persistência de postura como resultado do equipamento.","Prometer peso de carcaça dos machos.","Afirmar que a máquina entrega ração peletizada.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'O senhor já mistura milho com concentrado. A diferença é fazer isso com moagem uniforme e mistura homogênea, com a batida pesada — cada ave come a mesma mistura, e não o mais grosso que sobrou no cocho. Quem cuida da fórmula é o seu técnico; a máquina entrega a mistura e o peso.', 'Poedeira colonial da Embrapa, criada solta, que põe ovo caipira e no fim ainda vira carcaça. O produtor desse perfil tem milho e compra concentrado. Encaixe direto de Compacta JR/01: moer o milho, misturar o concentrado e fechar o saco com peso conferido.', 'Agricultura familiar em todo o país; genética desenvolvida pela Embrapa Suínos e Aves, em Concórdia-SC.', null, '🥚', 'aprovado', true, '{"Confirmar peso da poedeira, idade e peso de abate dos machos no material técnico vigente da Embrapa.","Não há dado de ovos/ano de fonte confirmada — não citar número."}'::text[], '{"embrapa-suinos-aves","rostagno-tabelas","mapa-alimentacao-animal","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1250),
  ('linhas-coloniais', 'Linhas coloniais comerciais (Paraíso Pedrês, Colonial 041, Master Griss, Caipirão)', '{"Paraíso Pedrês","Colonial 041","Master Griss","Caipirão","frango colonial comercial"}'::text[], 'aves', 'caipira', 'linhagem', 'Linhagens caipiras/coloniais de corte de empresas de genética (Globoaves e outras)', 'Carne de frango caipira/colonial para agroindústria e mercado regional.', 'Grupo de linhagens rústicas de crescimento intermediário para carne caipira, com plumagem variada (pedrês, vermelha, griss). Adaptadas à criação a campo e a ciclos mais longos que os do frango industrial. O ''Caipirão'' é o tipo mais pesado da família.', '{"caipira","colonial","integracao"}'::text[], '{"frango_inicial","frango_crescimento","frango_final","caipira"}'::text[], 'caipira', null, null, 'Faixa de referência: cerca de 2,2 a 3 kg conforme a linha e a idade, com abate por volta de 70 a 90 dias. Varia com linha, sexo e manejo. O dado oficial está no catálogo da empresa de genética, edição vigente.', 'Faixa de referência: consumo diário menor que o do frango industrial, mas consumo total por ave maior pelo ciclo mais longo. Puxar o histórico de consumo por lote do próprio cliente antes de dimensionar.', null, '{}'::text[], '{"ração farelada completa por fase","concentrado + milho próprio ou comprado a granel","piquete e verde como complemento"}'::text[], '{"farelada"}'::text[], '{"milho","sorgo","farelo-soja","concentrado-proteico","nucleo-premix","calcario-calcitico","fosfato-bicalcico","sal-comum","farelo-trigo","oleo-gordura","casquinha-soja","adsorvente-micotoxinas"}'::text[], '{"A linhagem pode ser alimentada com diferentes formas físicas conforme o programa nutricional e o manejo. A Branorte fornece equipamentos para produção de ração FARELADA; peletização exige processo adicional não incluído.","As linhas citadas são de empresas distintas e têm exigências e curvas próprias — não tratar como um bloco único na hora de formular.","Programas de caipira certificado impõem regras de ingrediente e de idade mínima de abate."}'::text[], '{"Com qual linha o senhor trabalha hoje e quem fornece o pinto?","Quantas aves aloja por lote e quantos lotes ficam alojados ao mesmo tempo?","Roda só a fórmula colonial ou também tem frango industrial na propriedade?","Quantas fórmulas diferentes precisam sair na mesma semana?","O milho entra a granel ou ensacado? Tem onde armazenar?"}'::text[], '{}'::text[], 'Recepção e moagem de milho, dosagem por caçamba de pesagem e mistura em batidas maiores. Linha colonial roda em paralelo à fórmula industrial quando o cliente atende os dois mercados. Perfil de Compacta 02/03 em diante, conforme o kg/h.', '{"MOEGA","ELEVADOR","MOINHO","MISTURADOR","CACAMBA_PESAGEM","TRANSPORTADOR","SILO","ENSACADEIRA"}'::text[], 'Aqui o cliente já tem escala: agroindústria ou integração de nicho com vários lotes ao mesmo tempo. O ganho está em produzir a linha colonial dentro de casa, com pesagem controlada por batida, em vez de depender de fornecedor externo para uma fórmula de baixo giro.', '{"Prometer peso, idade de abate ou conversão alimentar como resultado do equipamento.","Afirmar que a fábrica melhora a carne ou o rendimento de carcaça.","Afirmar que a máquina entrega ração peletizada.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'A ração colonial é outra linha, não é a mesma do frango de granja. Quanto o senhor paga hoje no saco dela? Fazendo em casa o senhor roda a colonial junto com o resto, com a batida pesada e conferida — a conta a gente fecha com o preço que o senhor me passar.', 'Família de linhagens coloniais de corte, abate entre 70 e 90 dias conforme a linha e o manejo — o dado oficial está no catálogo da empresa de genética. Público de agroindústria de caipira e produtor médio. A fórmula colonial é linha à parte da industrial e costuma girar pouco; conferir o preço do saco que ele paga hoje antes de falar em conta.', 'Interior de São Paulo, Sul, Minas Gerais e Nordeste — agroindústrias e produtores de frango caipira.', 'paraiso-pedres', '🐓', 'aprovado', true, '{"Confirmar peso e idade de abate de cada linha no catálogo vigente da empresa de genética.","Confirmar quais linhas o cliente realmente usa antes de tratar as quatro no mesmo pacote."}'::text[], '{"embrapa-suinos-aves","rostagno-tabelas","mapa-alimentacao-animal","branorte-catalogo","branorte-engenharia"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1260),
  ('landrace', 'Landrace', '{"Landrace dinamarquês","linha materna Landrace"}'::text[], 'suinos', 'comercial', 'raca', 'Raça materna (linha fêmea), origem dinamarquesa/europeia', 'Matriz industrial e produção de carne magra em granja comercial.', 'Raça materna de corpo comprido, orelhas grandes caídas para frente e carne magra. Reconhecida por habilidade materna e prolificidade — leitegadas grandes e boa produção de leite. Entra na genética comercial principalmente como metade da matriz F1.', '{"integracao","independente","comercial"}'::text[], '{"pre_inicial","inicial","crescimento","terminacao","gestacao","lactacao","reprodutores"}'::text[], 'terminacao', null, null, 'Animal de grande porte. Peso de matriz e de reposição varia com a linha genética e com o programa da granja; usar o padrão do fornecedor de genética do cliente.', 'Faixa de referência: consumo muda muito entre gestação, lactação e reposição — a matriz em lactação é a que mais come. Trabalhar com a curva de alimentação do programa nutricional da granja, não com número fixo.', null, '{}'::text[], '{"ração farelada por fase produzida na granja","concentrado ou núcleo + milho e farelo de soja","dieta de matriz separada para gestação e lactação"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","concentrado-proteico","nucleo-premix","calcario-calcitico","fosfato-bicalcico","sal-comum","lisina","metionina","oleo-gordura","farelo-trigo","fitase-enzimas","adsorvente-micotoxinas"}'::text[], '{"A raça pode ser alimentada com diferentes formas físicas conforme o programa nutricional e o manejo. A Branorte fornece equipamentos para produção de ração FARELADA; peletização exige processo adicional não incluído.","Rações de leitão (pré-inicial e inicial) usam ingredientes lácteos e aditivos caros, normalmente comprados prontos — não prometer produzir tudo na granja.","Formulação e curva de alimentação são do nutricionista ou da integradora."}'::text[], '{"Quantas matrizes o senhor tem alojadas hoje?","A granja é ciclo completo, UPL ou só terminação?","Quantas fórmulas diferentes precisam rodar por semana?","É integrado ou independente? Quem define a fórmula?","O milho é próprio ou comprado? Recebe a granel ou ensacado?"}'::text[], '{}'::text[], 'Recepção e limpeza do milho, moagem, dosagem por caçamba de pesagem e mistura por batida. Granja com matriz exige troca frequente de fórmula, o que pesa no tempo de ciclo do misturador e na organização das caixas de dosagem.', '{"MOEGA","PRE_LIMPEZA","ELEVADOR","SILO","MOINHO","CACAMBA_PESAGEM","MISTURADOR","TRANSPORTADOR","ENSACADEIRA"}'::text[], 'Granja com matriz roda muitas fórmulas: gestação, lactação, pré-inicial, inicial, crescimento e terminação. Fazer isso comprando pronto significa estoque de vários produtos. Com fábrica própria, o cliente troca de fórmula por batida e mexe só no que precisa.', '{"Prometer número de leitões nascidos, desmamados ou conversão alimentar como resultado do equipamento.","Prometer ganho de peso diário na terminação.","Afirmar que a máquina entrega ração peletizada.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'O senhor não faz uma ração só. É uma para a porca prenha, outra para a que está amamentando, e ainda as do leitão. Comprando pronto, é estoque de tudo isso. Fazendo aqui, troca a batida e pronto.', 'Linha materna: é metade da matriz F1 que sustenta a granja comercial. O que interessa para nós é o número de fórmulas — matriz em gestação e em lactação comem coisas diferentes. Quanto mais fórmula na semana, mais a fábrica própria se paga.', 'Sul (SC, PR, RS), Minas Gerais e Goiás — junto com Large White e Duroc, forma a base da genética da suinocultura comercial brasileira.', 'landrace', '🐷', 'aprovado', true, '{"Números de desempenho e faixas dependem de manual oficial e de validação técnica."}'::text[], '{"embrapa-suinos-aves","rostagno-tabelas","mapa-alimentacao-animal","branorte-catalogo","branorte-engenharia"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1270),
  ('large-white', 'Large White (Yorkshire)', '{"Yorkshire","Large White inglês","linha materna LW"}'::text[], 'suinos', 'comercial', 'raca', 'Raça materna (linha fêmea), origem inglesa', 'Matriz industrial e produção de carne magra em granja comercial.', 'Raça materna de pelagem branca e orelhas eretas, pernil cheio e boa área de olho de lombo. Bom ganho de peso e conversão, com habilidade materna e prolificidade reconhecidas. Forma a outra metade da matriz F1 junto com o Landrace.', '{"integracao","independente","comercial"}'::text[], '{"pre_inicial","inicial","crescimento","terminacao","gestacao","lactacao","reprodutores"}'::text[], 'terminacao', null, null, 'Grande porte. Peso de matriz e de reposição segue o padrão da linha genética usada pela granja.', 'Faixa de referência: entre as matrizes, a de lactação é a de maior consumo diário; a gestação é restrita e controlada. Em volume total de ração, porém, a granja gasta mais em crescimento e terminação. Seguir a curva do programa nutricional da granja.', null, '{}'::text[], '{"ração farelada por fase produzida na granja","concentrado ou núcleo + milho e farelo de soja","dieta de lactação de alto consumo"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","concentrado-proteico","nucleo-premix","calcario-calcitico","fosfato-bicalcico","sal-comum","lisina","metionina","oleo-gordura","farelo-trigo","fitase-enzimas","adsorvente-micotoxinas"}'::text[], '{"A raça pode ser alimentada com diferentes formas físicas conforme o programa nutricional e o manejo. A Branorte fornece equipamentos para produção de ração FARELADA; peletização exige processo adicional não incluído.","Rações de leitão continuam sendo compradas prontas na maioria das granjas.","Formulação é do nutricionista ou da integradora."}'::text[], '{"Quantas matrizes estão em lactação por vez?","Quantos kg de ração de lactação a granja consome por mês?","O senhor compra ração pronta, concentrado ou núcleo?","Quem faz a formulação hoje?","Tem silo e recebe milho a granel ou ainda trabalha ensacado?"}'::text[], '{}'::text[], 'Mesma linha da granja com matriz: recepção, moagem, pesagem por caçamba e mistura por batida, com troca frequente de fórmula. Ração de lactação costuma ser o item de maior volume.', '{"MOEGA","PRE_LIMPEZA","ELEVADOR","SILO","MOINHO","CACAMBA_PESAGEM","MISTURADOR","TRANSPORTADOR","ENSACADEIRA"}'::text[], 'A conta que fecha aqui é a da ração de lactação: alto consumo, fórmula cara, comprada pronta. Quando o cliente tem milho e compra só o concentrado, a fábrica própria muda o custo desse item. O equipamento entrega mistura homogênea e batida pesada — o resto é nutrição.', '{"Prometer prolificidade, leitões desmamados ou conversão como resultado do equipamento.","Prometer que a fábrica melhora a produção de leite da matriz.","Afirmar que a máquina entrega ração peletizada.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'A porca que está amamentando é a que mais come por dia e a fórmula dela é cara. O grosso do volume da granja continua na engorda. Se o milho é seu, dá para mexer nas duas contas — mas quem fecha o número é o preço que o senhor paga hoje pelo saco.', 'A outra metade da matriz F1. Público de granja comercial com muitas fórmulas rodando. A ração de lactação é boa porta de entrada da conversa por ser fórmula cara e de consumo diário alto por matriz — mas o volume que dimensiona a fábrica está em crescimento e terminação.', 'Sul do Brasil e demais cinturões de suinocultura integrada.', 'large-white', '🐷', 'aprovado', true, '{"Números de desempenho e faixas dependem de manual oficial e de validação técnica."}'::text[], '{"embrapa-suinos-aves","rostagno-tabelas","mapa-alimentacao-animal","branorte-catalogo","branorte-engenharia"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1280),
  ('duroc', 'Duroc', '{"Duroc-Jersey","linha paterna Duroc","terminador vermelho"}'::text[], 'suinos', 'comercial', 'raca', 'Raça paterna/terminadora, origem americana, pelagem vermelha', 'Macho terminador em cruzamento comercial; carcaça com marmoreio.', 'Raça paterna de pelagem avermelhada, rústica, com bom ganho de peso e deposição de gordura intramuscular (marmoreio). Usada como terminadora sobre matriz F1 quando o programa busca carne magra com mais sabor.', '{"comercial"}'::text[], '{"crescimento","terminacao","reprodutores"}'::text[], 'terminacao', null, null, 'Faixa de referência: o produto do cruzamento vai para abate por volta de 115 a 120 kg, conforme o programa do frigorífico. O peso do reprodutor segue o padrão da linha genética.', 'Faixa de referência: o consumo diário sobe ao longo do crescimento e da terminação, chegando ao maior valor no final. Varia com peso, genética, ambiente e forma física da ração — usar a curva do programa da granja.', null, '{}'::text[], '{"ração farelada de crescimento e terminação","concentrado ou núcleo + milho próprio","dieta de terminação com energia e aminoácidos ajustados"}'::text[], '{"farelada"}'::text[], '{"milho","sorgo","farelo-soja","concentrado-proteico","nucleo-premix","oleo-gordura","lisina","metionina","calcario-calcitico","fosfato-bicalcico","sal-comum","ddg-ddgs","fitase-enzimas","adsorvente-micotoxinas"}'::text[], '{"A raça pode ser alimentada com diferentes formas físicas conforme o programa nutricional e o manejo. A Branorte fornece equipamentos para produção de ração FARELADA; peletização exige processo adicional não incluído.","Marmoreio depende de genética, peso de abate e programa nutricional — não do equipamento.","Programas de carne diferenciada podem restringir ingredientes; conferir antes."}'::text[], '{"Quantos animais o senhor tem na fase de terminação por vez?","Quantos kg de ração saem por dia hoje?","Usa Duroc como terminador ou outra linha paterna?","Vende para frigorífico com programa de carne diferenciada?","O milho é próprio? Quanto colhe por safra?"}'::text[], '{}'::text[], 'Terminação é volume: poucas fórmulas, muita tonelagem. Pesa a vazão do moinho e o tempo de ciclo do misturador, mais transporte para os silos de baias.', '{"MOINHO","MISTURADOR","CACAMBA_PESAGEM","SILO","TRANSPORTADOR","ENSACADEIRA"}'::text[], 'Na terminação o volume de ração é o maior da granja e a fórmula é simples. É onde a fábrica própria trabalha melhor: bater grande quantidade de poucas fórmulas, com milho da propriedade. O equipamento entrega a mistura; a fórmula continua com o nutricionista.', '{"Prometer marmoreio, rendimento de carcaça ou conversão como resultado do equipamento.","Prometer ganho de peso diário.","Afirmar que a máquina entrega ração peletizada.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'Na engorda o senhor faz quase sempre a mesma ração, só que muita. É o tipo de trabalho em que a fábrica não para e o milho da propriedade rende.', 'Linha paterna usada para dar carcaça e marmoreio. Interessa para nós pela fase de terminação: muito volume, pouca variação de fórmula. Esse é o cenário mais favorável para a fábrica na propriedade.', 'Sul e Sudeste — linha terminadora em granjas comerciais.', 'duroc', '🐷', 'aprovado', true, '{"Números de desempenho e faixas dependem de manual oficial e de validação técnica."}'::text[], '{"embrapa-suinos-aves","rostagno-tabelas","mapa-alimentacao-animal","branorte-catalogo","branorte-engenharia"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1290),
  ('pietrain', 'Pietrain', '{"Pietrain belga","linha paterna Pietrain"}'::text[], 'suinos', 'comercial', 'raca', 'Raça paterna/terminadora, origem belga, hipermuscular', 'Macho terminador em programas focados em rendimento de carne magra.', 'Raça paterna branca com manchas pretas e orelhas eretas, de musculatura muito desenvolvida, principalmente no pernil, e carcaça bastante magra. Uso pontual como linha paterna em programas de genética; pouco difundida no Brasil tropical.', '{"comercial"}'::text[], '{"crescimento","terminacao","reprodutores"}'::text[], 'terminacao', null, null, 'Faixa de referência: machos adultos entre 250 e 300 kg, conforme a linha e o manejo. Confirmar no padrão do fornecedor de genética.', 'Faixa de referência: consumo diário do produto de terminação segue a curva normal da fase final, subindo com o peso. Depende de ambiente, genética e forma física da ração.', null, '{}'::text[], '{"ração farelada de crescimento e terminação","dieta de terminação com nível de aminoácidos ajustado à musculatura","concentrado ou núcleo + milho próprio"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","concentrado-proteico","nucleo-premix","lisina","metionina","oleo-gordura","calcario-calcitico","fosfato-bicalcico","sal-comum","fitase-enzimas","adsorvente-micotoxinas"}'::text[], '{"ALERTA TÉCNICO: alta frequência do gene halotano (HAL) — susceptibilidade ao estresse (PSS) e risco de carne PSE. Manejo que reduza estresse é parte do programa.","Baixa adaptação ao clima tropical — uso restrito e normalmente pontual no Brasil.","A raça pode ser alimentada com diferentes formas físicas conforme o programa nutricional e o manejo. A Branorte fornece equipamentos para produção de ração FARELADA; peletização exige processo adicional não incluído."}'::text[], '{"A granja usa Pietrain puro como terminador ou uma linha sintética com sangue Pietrain?","Já teve problema de carne PSE ou perda por estresse no embarque?","Qual o clima e o tipo de instalação — tem climatização nas baias de terminação?","Quem define a dieta de terminação e os níveis de aminoácido?","Quantos animais na fase final por vez?"}'::text[], '{}'::text[], 'Mistura homogênea importa mais aqui: dieta de terminação com nível alto de aminoácidos exige dosagem correta dos micros e batida uniforme. Pesagem por caçamba ou balança é o ponto de atenção.', '{"MOINHO","MISTURADOR","BALANCA","CACAMBA_PESAGEM","TRANSPORTADOR"}'::text[], 'Programa que usa Pietrain trabalha com dieta de terminação bem específica. O que a Branorte entrega é dosagem confiável e mistura homogênea — a fórmula vem do nutricionista do cliente. Não vender performance de carcaça.', '{"Prometer rendimento de carcaça, percentual de carne magra ou conversão como resultado do equipamento.","Sugerir que ração ou equipamento resolvem o problema do gene halotano ou evitam carne PSE.","Afirmar que a máquina entrega ração peletizada.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'É um terminador de músculo, usado em programa específico. Primeiro me diga se o plantel é Pietrain puro ou linha sintética com sangue Pietrain. Se for puro, vale o senhor saber: a raça carrega com frequência o gene halotano, que deixa o animal sensível ao estresse e pode dar carne PSE — manejo tranquilo importa. Do nosso lado, o que garantimos é mistura uniforme e pesagem certa.', 'Linha paterna de musculatura muito desenvolvida, de uso pontual no Brasil. Tem um alerta técnico importante: alta frequência do gene halotano, ligado à síndrome do estresse suíno e ao risco de carne PSE, além de baixa adaptação ao calor. Vender equipamento, não genética.', 'Uso pontual como terminador em programas de genética; pouco difundida na suinocultura tropical brasileira.', 'pietrain', '🐷', 'aprovado', true, '{"Confirmar peso adulto do reprodutor no padrão do fornecedor de genética.","Confirmar com o cliente se o plantel é Pietrain puro ou linha sintética antes de falar de gene halotano."}'::text[], '{"embrapa-suinos-aves","rostagno-tabelas","mapa-alimentacao-animal","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1300),
  ('piau', 'Piau (nacional naturalizada)', '{"Piau brasileiro","suíno caipira","porco de banha"}'::text[], 'suinos', 'comercial', 'raca', 'Raça nacional naturalizada, tipo banha/rústico', 'Criação familiar e caipira — carne e banha para consumo e mercado local.', 'Raça brasileira naturalizada, de origem no centro do país, muito rústica e adaptada à criação extensiva e familiar. Tem boa deposição de gordura, perfil do tipo banha, e menor eficiência para carne magra que as raças industriais.', '{"familiar","caipira"}'::text[], '{"crescimento","terminacao","gestacao","lactacao"}'::text[], 'crescimento', null, null, 'Peso e idade de abate variam muito conforme o manejo da propriedade; não há padrão comercial fechado como nas linhas industriais.', 'Faixa de referência: consumo menor e menos padronizado que na granja comercial, porque o animal aproveita pasto e sobras. Levantar o consumo real na propriedade antes de dimensionar.', null, '{}'::text[], '{"ração farelada simples produzida na propriedade","concentrado ou núcleo comprado + milho próprio","raspa de mandioca seca e pasto como complemento"}'::text[], '{"farelada"}'::text[], '{"milho","raspa-mandioca","farelo-soja","concentrado-proteico","nucleo-premix","farelo-trigo","farelo-arroz","quirera-arroz","calcario-calcitico","sal-comum","fosfato-bicalcico"}'::text[], '{"A raça pode ser alimentada com diferentes formas físicas conforme o programa nutricional e o manejo. A Branorte fornece equipamentos para produção de ração FARELADA; peletização exige processo adicional não incluído.","Uso de sobras e restos de alimentação humana tem restrição legal e sanitária — não recomendar.","Tende a depositar gordura; se o objetivo for carne magra, o controle é de fórmula e manejo, não de equipamento."}'::text[], '{"Quantos porcos o senhor tem na propriedade hoje?","Cria e engorda ou só engorda?","O milho é seu? E mandioca, tem?","Compra concentrado ou ração pronta?","Cria mais alguma coisa — galinha, gado? O mesmo conjunto de moagem e mistura costuma atender, desde que a ração seja farelada."}'::text[], '{}'::text[], 'Moagem de milho e mandioca da propriedade e mistura com concentrado comprado. Batidas pequenas, operação simples, um operador. Perfil clássico de Compacta JR / Compacta 01.', '{"MOINHO","MISTURADOR","BALANCA","ENSACADEIRA","SUPORTE_BAG"}'::text[], 'É o produtor que já mistura milho com concentrado à mão. O moinho resolve a moagem da mandioca e do milho, e o misturador dá batida homogênea. Venda de máquina pequena, decisão rápida, e o cliente costuma ter mais bicho na propriedade além do porco.', '{"Prometer ganho de peso, rendimento de carcaça ou proporção de carne magra como resultado do equipamento.","Prometer que a ração feita em casa ''emagrece'' ou ''engorda'' o animal em prazo determinado.","Afirmar que a máquina entrega ração peletizada.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'O senhor já mói e mistura de algum jeito. A máquina só faz isso direito e mais rápido, e serve para os outros bichos da propriedade também. O concentrado o senhor continua comprando.', 'Suíno nacional rústico, criação familiar, engorda mais gordura que carne magra. Público da Compacta JR/01: tem milho na propriedade e compra concentrado. Vale perguntar o que mais ele cria — quase sempre tem galinha e gado junto, e a mesma máquina serve.', 'Goiás, Minas Gerais, São Paulo e produção familiar no interior de todo o Brasil.', null, '🐷', 'aprovado', true, '{"Não há padrão comercial de peso e idade de abate para a raça — não citar número sem levantar na propriedade."}'::text[], '{"embrapa-suinos-aves","mapa-alimentacao-animal","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1310),
  ('cruzamento-comercial', 'Cruzamento comercial (F1 Landrace x Large White + terminador Duroc/Pietrain)', '{"três raças","F1 x terminador","suíno comercial de abate","tri-cross"}'::text[], 'suinos', 'comercial', 'cruzamento', 'Suíno comercial de abate — três raças (matriz F1 x macho terminador)', 'Produção de suíno de abate para frigorífico e integração.', 'Modelo predominante na suinocultura comercial brasileira: fêmea F1 (Landrace x Large White), que reúne prolificidade e habilidade materna, cruzada com macho terminador (Duroc ou Pietrain) para carcaça magra. Aproveita a heterose do cruzamento.', '{"integracao","independente","comercial"}'::text[], '{"pre_inicial","inicial","crescimento","terminacao"}'::text[], 'terminacao', null, null, 'Faixa de referência: abate por volta de 115 a 120 kg, conforme o programa do frigorífico. O peso-alvo é definido pelo contrato de integração ou pelo comprador, não pela raça.', 'Faixa de referência: o consumo diário cresce ao longo do ciclo, ficando na casa dos 2 kg/dia no crescimento e chegando perto de 3 kg/dia na fase final. Varia com peso, genética, ambiente e forma física da ração — usar a curva de alimentação do programa nutricional da granja.', null, '{}'::text[], '{"ração farelada por fase produzida na granja","concentrado ou núcleo + milho e farelo de soja","rações de leitão normalmente compradas prontas"}'::text[], '{"farelada"}'::text[], '{"milho","sorgo","farelo-soja","concentrado-proteico","nucleo-premix","oleo-gordura","lisina","metionina","calcario-calcitico","fosfato-bicalcico","sal-comum","farelo-trigo","ddg-ddgs","fitase-enzimas","adsorvente-micotoxinas"}'::text[], '{"O cruzamento pode ser alimentado com diferentes formas físicas conforme o programa nutricional e o manejo. A Branorte fornece equipamentos para produção de ração FARELADA; peletização exige processo adicional não incluído.","Rações pré-inicial e inicial de leitão em geral continuam sendo compradas prontas por causa dos ingredientes especiais.","Em granja integrada, a fórmula e muitas vezes o fornecedor são definidos pela integradora — confirmar antes de dimensionar.","Peso e padrão de abate são definidos pelo frigorífico."}'::text[], '{"Quantos animais o senhor tem alojados e em que fases?","Quantos kg de ração a granja consome por dia hoje?","Quantas fórmulas diferentes precisam rodar na mesma semana?","É integrado? A integradora define ou fornece a ração?","O milho é próprio ou comprado? Recebe a granel? Tem silo?","Vai continuar comprando pronta a ração de leitão?"}'::text[], '{}'::text[], 'Linha completa: recepção e limpeza do grão, elevação para silo, moagem, dosagem por caçamba de pesagem, mistura por batida e transporte para silos de baia ou ensaque. É o perfil de fábrica que mais roda horas por dia.', '{"MOEGA","PRE_LIMPEZA","ELEVADOR","SILO","MOINHO","CACAMBA_PESAGEM","MISTURADOR","TRANSPORTADOR","ENSACADEIRA","BALANCA"}'::text[], 'É o que a maioria das granjas comerciais realmente cria. A ração é o maior custo da operação e o volume se concentra em crescimento e terminação. Fábrica na granja permite bater grande volume de poucas fórmulas com o milho da região. O que a Branorte garante é capacidade em kg/h, dosagem por peso e mistura homogênea.', '{"Prometer conversão alimentar, ganho de peso diário ou rendimento de carcaça como resultado do equipamento.","Prometer redução percentual de custo da ração sem ter o preço real dos insumos do cliente.","Afirmar que a máquina entrega ração peletizada.","Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'A ração é o maior custo da sua granja e o grosso dela sai na engorda. A pergunta é simples: quantos quilos por dia o senhor precisa e quantas fórmulas diferentes. Com isso eu monto a fábrica no tamanho certo, sem sobra e sem gargalo.', 'Suíno de três raças, o padrão das granjas comerciais. Aqui não se vende raça, se vende tonelagem: o volume está em crescimento e terminação. Pergunte quantos kg de ração saem por dia e quantas fórmulas rodam por semana — dessas duas respostas sai o tamanho da fábrica.', 'Suinocultura integrada do Sul (SC, PR, RS), com expansão em Mato Grosso, Goiás e Minas Gerais.', 'suinos-terminacao', '🐂', 'aprovado', true, '{"Confirmar peso-alvo de abate com o contrato do frigorífico do cliente.","Consumo diário por fase deve vir da curva do programa nutricional da granja, não do card.","Auditoria: (g) Campo \"emoji\" ausente. Todos os outros 8 cards têm o campo; este termina em \"pendencias\" e quebra a consistência do schema — no render o card sai sem o ícone de espécie."}'::text[], '{"embrapa-suinos-aves","rostagno-tabelas","mapa-alimentacao-animal","branorte-catalogo","branorte-engenharia"}'::text[], 'Auditoria 2026-08-03', null, null, null, 1320)
