-- ============================================================================
-- Guia do Vendedor — seed de ANIMAIS (parte 2: raças e linhagens)
--
-- Redigidos com base no texto do guia.html antigo e submetidos a auditoria
-- adversarial. As correções dos auditores estão APLICADAS. Entre elas:
--   • Senepol citava a ABCZ como fonte — é taurino, não zebuíno;
--   • Girolando "de 1/2 a 7/8" era invenção: agora remete à associação da raça;
--   • Holandês tinha o superlativo apenas reescrito ("a que mais exige ração");
--   • Jersey atribuía teor de sólidos do leite ao equipamento;
--   • silagem, óleo e melaço apareciam em materias_comuns sem a ressalva de que
--     a linha processa produto SECO.
--
-- Todos entram com pendente_validacao = true: número de desempenho por
-- linhagem só vira número fechado com manual oficial (edição, ano, sexo, idade).
-- ============================================================================

on conflict (slug) do update set nome = excluded.nome, sinonimos = excluded.sinonimos, especie = excluded.especie, subgrupo = excluded.subgrupo, tipo = excluded.tipo, classificacao = excluded.classificacao, finalidade = excluded.finalidade, resumo = excluded.resumo, sistemas = excluded.sistemas, fases = excluded.fases, fase_estudo = excluded.fase_estudo, peso_min_kg = excluded.peso_min_kg, peso_max_kg = excluded.peso_max_kg, peso_nota = excluded.peso_nota, consumo_ref = excluded.consumo_ref, consumo_unidade = excluded.consumo_unidade, consumo_fatores = excluded.consumo_fatores, tipos_alimentacao = excluded.tipos_alimentacao, forma_fisica = excluded.forma_fisica, materias_comuns = excluded.materias_comuns, restricoes = excluded.restricoes, perguntas = excluded.perguntas, sinais_falta_info = excluded.sinais_falta_info, processo = excluded.processo, equipamentos = excluded.equipamentos, argumento = excluded.argumento, promessas_proibidas = excluded.promessas_proibidas, branorte = excluded.branorte, explicar_cliente = excluded.explicar_cliente, resumo_30s = excluded.resumo_30s, regiao = excluded.regiao, imagem_slug = excluded.imagem_slug, emoji = excluded.emoji, status = excluded.status, pendente_validacao = excluded.pendente_validacao, pendencias = excluded.pendencias, fontes = excluded.fontes, autor = excluded.autor, revisor_tecnico = excluded.revisor_tecnico, revisado_em = excluded.revisado_em, proxima_revisao = excluded.proxima_revisao, ordem = excluded.ordem;
